import {openCareerStore,defaultCareerName} from './career-storage.js';
import {transitionDelay} from './presentation-timing.js';
import {mountSkillCheck} from './skill-checks.js';
import {PORTRAIT_CROPS} from './portrait-crops.js';
import * as E from './engine.js';
const $=q=>document.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signed=(n,digits=0)=>{const value=Number(Number(n).toFixed(digits));return (value>0?'+':value<0?'−':'')+Math.abs(value).toFixed(digits);};
const growthRange=p=>{const room=Math.max(0,100-E.overall(p));return [Math.min(room,Math.max(0,Math.round(p.growth/2-4))),Math.min(room,Math.max(0,Math.round(p.growth/2+4)))];};
const cash=n=>'$'+Math.round(n).toLocaleString('en-US');
let s,view='hq',roleFilter='ALL',regionFilter='LCS',draftRole='ALL',choice=0,scoutRegion='ALL',setupRegion='LCS',managerDraft='',renewYears={},legacy=null,loadError='',seasonPhase=null,seasonYear=null,profileIds=[],currentProfile=null;
let sharedAchievements=E.emptyAchievementBook(),achievementFilter='All';
const careerDB=openCareerStore(globalThis.indexedDB,globalThis.localStorage);
let careerStore,activeSlot=null,slotNameDraft='',slotsBusy=false;
try{careerStore=await careerDB;sharedAchievements=await careerStore.achievementBook();const record=await careerStore.initialize(E.validateSave,localStorage.getItem('under-the-rift-v2'));if(record){s=E.validateSave(record.data);activeSlot=record.id;}legacy=localStorage.getItem('frontoffice-v1');}catch{loadError='Could not load the saved career. Your existing save has been left untouched. You can open Saved careers or import a backup.';}
let started=!!s;if(!s)s=E.newGame();regionFilter=s.teams[s.team].region;if(s.match)view='match';
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
async function save(){if(!started||!activeSlot)return true;E.updateDiscoveries(s);const id=activeSlot,data=structuredClone(s);try{if(!careerStore)throw Error('Storage unavailable.');await careerStore.write(id,data);sharedAchievements=await careerStore.achievementBook();return true;}catch(error){toast('Could not save: '+error.message+' Export a backup in Settings.');return false;}}
function useCareer(data,id){s=data;activeSlot=id;started=true;loadError='';view=s.match?'match':'hq';regionFilter=s.teams[s.team].region;roleFilter='ALL';scoutRegion='ALL';draftRole='ALL';seasonYear=null;seasonPhase=null;profileIds=[];currentProfile=null;renewYears={};marketTab='overview';marketRole='ALL';marketClub='ALL';marketQuery='';marketPage=0;marketListed=false;$('#modal').close();render();}
async function addCareer(data,name){if(!careerStore)throw Error('Storage unavailable. Export your current career and try reloading.');if(!await save())throw Error('The current career could not be saved.');E.updateDiscoveries(data);const record=await careerStore.create(data,name);sharedAchievements=await careerStore.achievementBook();useCareer(data,record.id);toast('New career saved separately.');}
async function savedCareers(){if(slotsBusy)return;slotsBusy=true;try{if(!await save())return;if(!careerStore)throw Error('Storage unavailable.');const rows=await careerStore.list();$('#modal').innerHTML=`<div class="panelhead"><h2>Saved careers</h2><button data-action="close" aria-label="Close saved careers">✕</button></div><div class="modalbody"><div class="actions"><button class="primary" data-action="new">＋ New career</button><button data-action="import">Import as new career</button></div><p>Each career autosaves separately on this browser. Export a file to back it up or move it to another device.</p><div class="savecards">${rows.map(r=>`<article class="savecard ${r.id===activeSlot?'current':''}"><div class="sectiontitle"><h3>${esc(r.name)}</h3>${r.id===activeSlot?'<span class="tag gold">PLAYING</span>':''}</div><p><b>${esc(r.summary.team)}</b> · ${esc(r.summary.region)}</p><p>${esc(r.summary.manager)} · ${r.summary.year} · ${esc(r.summary.phase==='draft'?'Academy draft':r.summary.phase==='offseason'?'Offseason':r.summary.split)} · Week ${r.summary.step}</p><p class="muted">Saved ${esc(new Date(r.updated).toLocaleString())}</p><div class="actions"><button class="primary" data-load-slot="${esc(r.id)}" ${r.id===activeSlot?'disabled':''}>Continue career</button><button data-export-slot="${esc(r.id)}">Export</button>${r.id!==activeSlot?`<button data-delete-slot="${esc(r.id)}">Delete</button>`:''}</div><details><summary>Rename career</summary><form class="slot-rename" data-slot="${esc(r.id)}"><label>Career name<input name="slotname" value="${esc(r.name)}" maxlength="60" required></label><button type="submit">Save name</button></form></details></article>`).join('')||'<p>No saved careers yet. Start a new career above.</p>'}</div></div>`;if(!$('#modal').open)$('#modal').showModal();}catch(error){toast(error.message);}finally{slotsBusy=false;}}
async function handleSlotClick(b){if(slotsBusy)return;slotsBusy=true;try{if(!await save())return;const id=b.dataset.loadSlot||b.dataset.exportSlot||b.dataset.deleteSlot,record=await careerStore.read(id);if(!record)throw Error('Career not found.');if(b.dataset.loadSlot){const loaded=E.validateSave(structuredClone(record.data));await careerStore.activate(id);useCareer(loaded,id);toast('Career loaded.');}else if(b.dataset.exportSlot){download(JSON.stringify(record.data,null,2),'under-the-rift-'+record.name.replace(/[^a-z0-9-]/gi,'-')+'.json');}else if(id!==activeSlot&&confirm('Permanently delete “'+record.name+'”? Export it first if you want a backup.')){await careerStore.remove(id);slotsBusy=false;await savedCareers();}}catch(error){toast(error.message);}finally{slotsBusy=false;}}
function commit(){E.recordCareer(s);save();render();}
// Original club emblems, tinted with each organization's existing color.
const logoShapes=[
'<path d="M14 28a8 8 0 0111-7 11 11 0 0120 3 7 7 0 01-1 14H20a7 7 0 01-6-10z"/><path d="M28 29c-6 0-7 10 0 10h9v-5h-7c-2 0-2-2 0-2h8v-5z" fill="#20242d"/>',
'<path d="M20 15l20 5 5 10-10 7 8 8H18l7-14-5-7z"/><path d="M29 22h6l-2 4z" fill="#20242d"/>',
'<path d="M31 43C12 40 12 18 14 17c13 0 20 10 18 17 2-17 13-20 19-21 2 18-7 26-17 29v5h-4z"/>',
'<path d="M15 20l17-6 17 6-5 21-12 5-12-5z"/><path d="M22 25h9v9h-9zm13 0h9v9h-9zM28 37h8l-4 5z" fill="#20242d"/>',
'<path d="M20 16h29l-6 9H27l-3 5h18l4 7-8 9H12l7-9h15l3-3H18l-5-7z"/>',
'<path d="M18 14l14 6 14-6 5 18-8 15H21L13 32z"/><path d="M22 27l8 4-6 3zm20 0l-8 4 6 3zM27 39h10l-5 5z" fill="#20242d"/>',
'<path d="M17 16h32l-8 9H25l-3 4h18l7 7-9 12H10l8-10h15l3-4H19l-8-8z"/>',
'<path d="M12 21l20-6 20 6-6 21-14 7-14-7z"/><path d="M18 25h12v10H18zm16 0h12v10H34z" fill="#20242d"/>',
'<path d="M9 18h46l-7 8H37v22H27V26H16zM8 30h14v6H12zm6 10h8v6h-4z"/>',
'<path d="M16 18l8 6 8-12 8 12 8-6-5 25H21zM21 46h22v4H21z"/>',
'<path d="M14 17h10v12h16V17h10v31H40V37H24v11H14z"/>',
'<path d="M15 16h19l17 16-17 17H15z"/><path d="M25 24v17l11-9z" fill="#20242d"/>',
'<path d="M27 12h18L33 28h17L22 52l5-18H14z"/>',
'<path d="M15 27h34l-4 14-13 8-13-8zM17 19h30v5H17zM23 12h4v5h-4zm14 0h4v5h-4z"/>',
'<path d="M12 14l17 10h6l17-10-5 29-15 8-15-8z"/><path d="M19 28l10 6-7 3zm26 0l-10 6 7 3zM28 42h8l-4 5z" fill="#20242d"/>',
'<path d="M12 15h12l8 10 8-10h12L38 32l14 17H40L32 39l-8 10H12l14-17z"/>',
'<path d="M10 41l15-25 8 14 8-16 14 27-23 10z"/><path d="M24 29l-5 10h11zm17-3l-6 13h12z" fill="#20242d"/>',
'<path d="M17 14h21l12 9-7 10 7 8-10 9H17z"/><path d="M27 23h10v6H27zm0 15h11v5H27z" fill="#20242d"/>'
];
const teamIcon=t=>E.TEAM_LOGOS[t.tag]?`<img class="teamcrest officialcrest" src="${E.TEAM_LOGOS[t.tag]}" alt="${esc(t.name)} logo" style="--team-color:${t.color}"/>`:`<svg class="teamcrest" viewBox="0 0 64 64" role="img" aria-label="${esc(t.name)} crest"><path d="M32 1L60 9V35Q57 53 32 63Q7 53 4 35V9Z" fill="#20242d"/><path d="M32 5L56 12V34Q53 49 32 58Q11 49 8 34V12Z" fill="${t.color}"/><path d="M11 15L32 9l21 6v6L32 15l-21 6z" fill="#ffffff" opacity=".2"/><g fill="#f1eee8">${logoShapes[t.id%logoShapes.length]}</g></svg>`;
const teamLabel=(t,full=false)=>`<span class="teamlabel">${teamIcon(t)}<span>${esc(full?t.name:t.tag)}</span></span>`;
const badge=(t,big=false)=>`<div class="badge ${big?'big':''}" style="color:${t.color}">${teamIcon(t)}</div>`;
let portraitSerial=0;
function portrait(p,size=''){const n=E.MALE_PORTRAITS.includes(p.portrait)?p.portrait:E.MALE_PORTRAITS[0],modern=n>=16,tile=modern?(n-16)%64:n,file=modern?'players-'+['a','b','c','d','e','f','g','h'][Math.floor((n-16)/64)]:'players',crop=PORTRAIT_CROPS[file][tile],clip='portrait-clip-'+(++portraitSerial);return `<div class="portrait ${size}" role="img" aria-label="${esc(p.name)} portrait"><svg viewBox="${crop.join(' ')}" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs><clipPath id="${clip}" clipPathUnits="userSpaceOnUse"><rect x="${crop[0]}" y="${crop[1]}" width="${crop[2]}" height="${crop[3]}"/></clipPath></defs><image clip-path="url(#${clip})" href="assets/${file}.png" width="1254" height="1254"/></svg></div>`;}

function champion(niche){const n=E.NICHES[niche];return `<div class="champ" role="img" aria-label="${esc(n.champ)}" title="${esc(n.champ)} · ${esc(niche)}" style="background-position:${n.art%4/3*100}% ${Math.floor(n.art/4)/3*100}%"></div>`;}
const portraitWithChamp=(p,niche=p.niches[0])=>`<div class="portraitwrap">${portrait(p)}${champion(niche)}</div>`;
const playerName=p=>p?.secretProspect?`<span class="special-player-name">${esc(p.name)}</span>`:esc(p?.name||'Passed');
function captainBadge(p){return p.secretProspect||p.team>=0&&E.teamCaptain(s,p.team)?.id===p.id?'<span class="captain-badge" title="Club captain · Communication gives a small bonus to calls">C · Captain</span>':'';}
function captainPanel(team=s.team){const p=E.teamCaptain(s,team);return p?`<aside class="captain-summary"><div><span class="kicker">Club captain</span><strong>${playerName(p)}</strong></div><span>Communication <b>${Math.round(E.effectiveSkill(p,'Communication'))}</b></span><span class="captain-effect">+${(E.captainCallBonus(s,team)*100).toFixed(1)} percentage points to calls</span></aside>`:'';}
const traitName=t=>t==='Captain'?'Leadership':['Jhinaholic','FioraMain'].includes(t)?t:t.replace(/([a-z])([A-Z])/g,'$1 $2');
const trait=t=>`<span class="trait ${E.RARE_TRAITS.includes(t)?'raretrait':E.SPECIAL_TRAITS.includes(t)?'signaturetrait':''}" title="${esc(E.TRAITS[t])}">${esc(traitName(t))}</span>`;
const locked=()=>s.match?'disabled':'';
const heading=(title,subtitle='',actions='')=>`<div class="heading"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
function formBar(p){return `<div class="form"><span>Form</span><div class="formbar"><i style="width:${(p.form-50)*2}%"></i></div><b>${Math.round(p.form)}</b></div>`;}
function nextAction(){if(E.managerDecisionPending(s))return '<button class="primary" data-view="career">Choose your next club →</button>';if(s.celebration)return '<button class="primary" data-action="celebration">Celebrate the title →</button>';if(s.match)return '<button class="primary" data-view="match">Resume series →</button>';if(s.clubEvent)return '<button class="primary" data-action="orgevent">Club decision →</button>';if(s.phase==='internationalGroups')return '<button class="primary" data-action="play">Resolve Worlds groups →</button>';if(s.phase==='draft')return s.draft.complete?'<button class="primary" data-action="spring">Begin Spring →</button>':'<button class="primary" data-view="academy">Enter academy draft →</button>';if(s.phase==='offseason')return marketNext();return `<button class="primary" data-action="play">${E.opponent(s)===undefined?(s.phase==='regular'?'Advance matchweek →':'Follow tournament →'):'Play series →'}</button>`;}
function infoBar(){const t=s.teams[s.team];return `<div class="briefstats"><div><span>${t.region} record</span><b>${t.wins} – ${t.losses}</b></div><div><span>Chemistry</span><b>${E.chemistry(s)}%</b></div><div><span>Club funds</span><b>${cash(s.budget)}</b></div></div>`;}
function pairRow(a,b,chosenA,chosenB){return `<div class="matchrow"><div class="person">${portraitWithChamp(a,chosenA)}<div class="personname"><button class="linkbutton" data-profile="${a.id}"><strong>${esc(a.name)}</strong></button><small>${esc(chosenA)}</small></div><span class="ovr">${E.overall(a)}</span></div><span class="role">${a.role}</span><div class="person away">${portraitWithChamp(b,chosenB)}<div class="personname"><button class="linkbutton" data-profile="${b.id}"><strong>${esc(b.name)}</strong></button><small>${esc(chosenB)}</small></div><span class="ovr">${E.overall(b)}</span></div></div>`;}
function preview(){const opp=E.opponent(s);if(s.phase==='draft')return `<section class="panel"><div class="draftstrip"><div class="number">03</div><div><h2>Find your next generation.</h2><p style="margin:5px 0">Three academy picks. A whole year ahead.</p></div></div><div class="panelbody"><div class="draftpicks" style="padding:0;margin-bottom:22px">${[0,1,2].map((n)=>{const pick=s.draft.picks.filter(p=>p.team===s.team)[n];const p=pick&&E.getPlayer(s,pick.player);return `<div class="draftpick">${p?portrait(p,'small'):''}<div><strong>${p?esc(p.name):'Pick '+(n+1)}</strong><div class="muted textsmall">${p?p.role:'Academy selection'}</div></div></div>`;}).join('')}</div>${nextAction()}</div></section>`;
if(s.phase==='internationalGroups')return worldsPanel(s.worldsGroups,true);if(s.phase==='offseason')return marketClubPanel();
if(opp===undefined&&s.phase==='internationalPlayin'&&s.internationalByes?.includes(s.team))return `<section class="panel empty"><h2>A quarterfinal bye.</h2><p>Your seeding earned a direct quarterfinal place. Follow the play-in to find out who advances.</p>${nextAction()}</section>`;
if(opp===undefined)return `<section class="panel empty"><h2>${s.phase==='regular'?'A week to develop.':'The tournament continues.'}</h2><p>${s.phase==='regular'?'No match for your team this round. Training and the other region continue.':'Your team is out of this event. Follow the remaining matches and prepare for what comes next.'}</p>${nextAction()}</section>`;
const t=s.teams[s.team],o=s.teams[opp],a=E.starters(s),b=E.starters(s,opp),ca=E.composition(s),cb=E.composition(s,opp),ra=E.teamRating(s,s.team,s.phase!=='regular'),rb=E.teamRating(s,opp,s.phase!=='regular');return `<section class="panel"><div class="panelhead"><h2>Next match</h2>${nextAction()}</div><div class="versus"><div class="teamhero">${badge(t,true)}<div><h2>${esc(t.name)}</h2><p>${t.region} · ${t.wins}W ${t.losses}L</p></div></div><div class="ratingbattle"><span class="kicker">Team rating</span><div><b>${ra.toFixed(0)}</b><span class="divider">:</span><b>${rb.toFixed(0)}</b></div><span class="vs">VS</span></div><div class="teamhero away"><div><h2>${esc(o.name)}</h2><p>${o.region} · ${o.wins}W ${o.losses}L</p></div>${badge(o,true)}</div></div><div class="ratingscale" aria-label="Team rating comparison"><i style="width:${ra/(ra+rb)*100}%"></i></div><div class="comparisonhead"><span>YOUR FIVE · OVR</span><span>OPPONENT FIVE · OVR</span></div>${a.map((p,i)=>pairRow(p,b[i],ca.chosen[i],cb.chosen[i])).join('')}<div class="matchfooter"><div class="combo-list">${ca.links.filter(c=>!c.secretId||s.discoveries?.combos[c.secretId]).slice(0,3).map(c=>`<span class="tag" title="${esc(c[3])}">${c[2]}</span>`).join('')||'<span class="tag">Building a team identity</span>'}<span class="tag gold">+${ca.bonus.toFixed(1)} composition</span></div></div></section>`;}
function standingsTable(region,academyMode=false){let teams=academyMode?s.teams.filter(t=>t.region===region).sort((a,b)=>b.academyWins-a.academyWins||a.academyLosses-b.academyLosses):E.standings(s,region);return `<div class="tablewrap"><table><thead><tr><th>#</th><th>${region}${academyMode?' Academy':''}</th><th>W</th><th>L</th></tr></thead><tbody>${teams.map((t,i)=>`<tr class="${t.id===s.team?'you':''}"><td>${i+1}</td><td><span class="teamcell">${teamIcon(t)}${esc(t.tag)}${t.id===s.team?' · YOU':''}</span></td><td>${academyMode?t.academyWins:t.wins}</td><td>${academyMode?t.academyLosses:t.losses}</td></tr>`).join('')}</tbody></table></div>`;}
function hq(){const t=s.teams[s.team];return heading(`${esc(t.name)} club`,`${E.phaseLabel(s)} · ${s.year}`,nextAction())+`<div class="grid"><div>${s.clubEvent&&!s.match?`<section class="panel event-preview"><div class="panelbody"><span class="tag">CLUB DECISION</span><h2>${esc(s.clubEvent.title)}</h2><p>${esc(s.clubEvent.text)}</p><button class="primary" data-action="orgevent">Talk to the team →</button></div></section>`:''}${s.celebration?`<section class="panel champion-callout"><div class="panelbody"><h2>${esc(s.celebration.event)} champions!</h2><button class="primary" data-action="celebration">Lift the trophy →</button></div></section>`:''}${s.phase==='offseason'&&s.career?.jobs&&['open','dismissed'].includes(s.career.jobs.status)?'<section class="panel"><div class="panelhead"><h2>Your next chapter</h2><button data-view="career">View manager offers →</button></div><div class="panelbody">'+(s.career.jobs.fired?'The board has ended your contract. Three clubs have offered a fresh start.':'Other clubs are interested in you. Stay with your club or explore a new role before opening free agency.')+'</div></section>':''}${formerPreview()}${preview()}${s.event==='Worlds'&&s.phase!=='internationalGroups'&&s.worldsGroups?.year===s.year?worldsPanel(s.worldsGroups):''}${s.phase!=='offseason'?marketClubPanel():''}${schedulePanel()}${scrimCallout()}${clubStoriesPanel()}${broadcastPanel()}<section class="panel"><div class="panelhead"><h2>Club updates</h2><button class="small" data-action="reports">Development reports ${s.reports.length?'('+s.reports.length+')':''}</button></div>${(s.news.length?s.news:['Your career starts with three academy draft picks.']).slice(0,3).map(n=>`<div class="news">${esc(n)}</div>`).join('')}</section></div><aside><section class="panel">${infoBar()}${standingsTable(t.region)}</section>${rumorsPanel()}</aside></div>`;}
function rumorsPanel(){const items=E.regionalRumors(s);return `<section class="panel rumors"><div class="panelhead"><h2>Regional rumors</h2><span class="tag">${s.teams[s.team].region}</span></div>${items.map(r=>`<article>${teamIcon(s.teams[r.team])}<div><span class="rumorlabel">${esc(r.label)}</span><p>${esc(r.text)}</p></div></article>`).join('')}<div class="rumorfoot">Club needs are analyst projections. Confirmed moves come from the transfer wire.</div></section>`;}
function connectionPanel(ps=E.starters(s),academyMode=false){const pairs=academyMode?ps.flatMap((a,i)=>ps.slice(i+1).map(b=>[a,b])):[[ps[1],ps[2]],[ps[3],ps[4]],[ps[0],ps[1]]];if(!pairs.length)return '';return `<section class="panel"><div class="panelhead"><h2>${academyMode?'Academy connections':'Connections'}</h2></div><div class="panelbody">${pairs.map(([a,b])=>`<div class="pair"><span>${esc(a.name)} + ${esc(b.name)}</span><b>${E.familiarity(s,a.id,b.id)}%</b></div><div class="progress"><i style="width:${E.familiarity(s,a.id,b.id)}%"></i></div>`).join('')}</div></section>`;}
function playerCard(p,academyMode=false){const active=s.teams[s.team].lineup[p.role]===p.id;return `<article class="playercard"><div class="playerbanner">${academyMode?`<button class="portraitbutton" data-academy-chat="${p.id}" aria-label="${esc(p.name)} portrait">${portrait(p)}</button>`:portrait(p)}<span class="ovr">${E.overall(p)}</span></div><div class="cardbody"><div class="role">${p.role} · ${p.age} YEARS</div><h3>${playerName(p)}</h3>${captainBadge(p)}<div class="nicheline">${champion(p.niches[0])}<span>${esc(p.niches[0])}</span></div>${formBar(p)}<div style="margin-top:12px">${p.traits.map(trait).join('')}</div><div class="actions"><button class="small" data-profile="${p.id}">Profile</button>${academyMode?`<button class="small primary" data-callup="${p.id}" ${locked()}>Call up</button>`:!active?`<button class="small primary" data-starter="${p.id}" ${locked()}>Start</button>`:''}</div>${academyMode?`<div class="contractquote">${E.overall(p)-p.initial>=0?'+':''}${E.overall(p)-p.initial} OVR · ${p.games} academy games</div>`:''}</div></article>`;}
function roster(){const lineup=E.starters(s),bench=E.squad(s).filter(p=>!lineup.some(x=>x.id===p.id)),comp=E.composition(s);return heading('First team',`${E.squad(s).length} players`)+`<div class="teamratinghero"><span>TEAM RATING</span><strong>${E.teamRating(s).toFixed(0)}</strong></div>${captainPanel()}<div class="cards">${lineup.map(p=>playerCard(p)).join('')}</div>${connectionPanel()}${bench.length?`<div class="sectiontitle"><h2>Bench</h2></div><div class="cards">${bench.map(p=>playerCard(p)).join('')}</div>`:''}<div class="sectiontitle"><h2>Composition links</h2><button class="small" data-action="combinations">All combinations</button><span class="tag gold">+${comp.bonus.toFixed(1)} team rating</span></div><div class="traininggrid">${comp.links.filter(c=>!c.secretId||s.discoveries?.combos[c.secretId]).map(c=>`<article class="trainingcard"><h3>${c[2]}</h3><p class="textsmall">${c[0]} + ${c[1]}</p><p class="textsmall">${c[3]}</p></article>`).join('')||'<div class="notice">No composition links yet. Scout players whose niches complement your starting five.</div>'}</div>`;}
function training(){return heading('Training ground','Grow skills. Manage Form.', '<button class="small" data-action="reports">Development reports</button>')+`<section class="panel"><div class="panelbody recovery-controls"><button class="primary" data-action="recoverfive" ${locked()}>Starting five → Recovery</button><button data-action="balancefive" ${locked()}>Starting five → Balanced</button><label class="checklabel"><input type="checkbox" id="auto-recovery" ${s.recovery.enabled?'checked':''} ${locked()}> Automatic recovery</label><label class="threshold">Recover above <b id="threshold-value">${s.recovery.threshold}</b> fatigue<input id="recovery-threshold" type="range" min="10" max="90" step="5" value="${s.recovery.threshold}" ${locked()}></label><button class="small" data-action="traininghelp">How it works</button></div></section>${[['First team',E.squad(s)],['Academy',E.academy(s)]].map(([title,ps])=>`<div class="sectiontitle"><h2>${title}</h2><span>${ps.length} players</span></div><div class="traininggrid">${ps.map(trainingPlayer).join('')||'<p>No players in this squad.</p>'}</div>`).join('')}`;}
function trainingPlayer(p){return `<article class="trainingcard"><div class="person">${portrait(p)}<div><h3>${playerName(p)}</h3>${captainBadge(p)}<p class="textsmall" style="margin:4px 0">${p.role} · ${p.squad==='academy'?'Academy':'First team'}</p></div><span class="ovr">${E.overall(p)}</span></div><div class="fieldrow"><label>Focus<select data-focus="${p.id}" ${locked()}>${E.FOCUSES.map(f=>`<option ${f===p.focus?'selected':''}>${f}</option>`).join('')}</select></label><label>Intensity<select data-intensity="${p.id}" ${locked()}>${['Light','Normal','Intense'].map(f=>`<option ${f===p.intensity?'selected':''}>${f}</option>`).join('')}</select></label></div>${formBar(p)}<div class="pair"><span>Fatigue</span><b>${Math.round(p.fatigue)}</b></div><div class="progress"><i style="width:${p.fatigue}%;background:${p.fatigue>55?'#ad5a43':'#dc7c37'}"></i></div><div class="fatigue-impact">Current fatigue drag: <b>−${E.fatiguePenalty(p).toFixed(1)} Form/session</b></div><div class="textsmall muted">Last session: ${esc(p.lastTraining||'Not trained yet')}${p.lastTraining?` · fatigue cost −${p.lastFatiguePenalty.toFixed(1)} Form`:''}</div><button class="small" data-profile="${p.id}" style="margin-top:15px">Player profile ↗</button></article>`;}
function prospectNote(p){if(!p.scout)return 'Early report: development potential is still unclear.';if(p.learning>1.22&&p.growth>24)return 'Possible prodigy. Fast learner with substantial room to grow.';if(p.learning>1.1)return 'Promising learner. Strong training could unlock a starting role.';return 'Steady prospect. Improvement will take time and consistent opportunities.';}
function prospectCard(p,draft=false){const terms=E.scoutTerms(s,p),range=terms.range,o=E.overall(p);return `<article class="scoutcard"><div class="person">${portrait(p)}<div><h3>${playerName(p)}</h3>${captainBadge(p)}<span class="muted textsmall">${p.role} · ${p.age} years · ${p.homeRegion}</span></div><span class="ovr">${range?Math.max(50,o-range)+'–'+Math.min(100,o+range):o}</span></div><div class="niches">${p.niches.map(n=>`<span class="tag">${esc(n)}</span>`).join('')}</div>${p.traits.map(trait).join('')}<p>${prospectNote(p)}</p><div class="contractquote">${p.scout===2?'High scouting confidence':p.scout===1?'Moderate scouting confidence':'Low scouting confidence'}${draft?'':` · Agent target ${cash(E.askingTerms(s,p).salary)}/year`}</div><div class="actions" style="margin-top:15px"><button class="small" data-scout="${p.id}" ${locked()} ${s.scouting.includes(p.id)||p.scout===2||E.spendable(s)<E.scoutTerms(s,p).cost?'disabled':''}>${s.scouting.includes(p.id)?'Scouting…':p.scout===2?'Fully scouted':'Scout · '+cash(E.scoutTerms(s,p).cost)}</button>${draft?`<button class="primary small" data-draft="${p.id}" ${s.draft.complete||E.academy(s).length>=6||!E.draftEligible(s,p,s.team)?'disabled':''}>${E.draftEligible(s,p,s.team)?'Draft':'LCS / LCK draft only'}</button>`:`<button class="primary small" data-sign="${p.id}" ${locked()} ${s.phase==='draft'?'disabled':''}>Negotiate contract</button>`}</div></article>`;}
function filters(type,selected){return `<div class="filters">${['ALL',...E.ROLES].map(r=>`<button class="small ${selected===r?'active':''}" data-${type}="${r}">${r==='ALL'?'All roles':r}</button>`).join('')}</div>`;}
function networkPanel(){return `<section class="panel"><div class="panelhead"><h2>Regional scouting networks</h2><span>Club-owned connections</span></div><div class="networkgrid">${E.regions(s).map(r=>{const level=E.scoutingNetwork(s,r),cost=E.networkUpgradeCost(s,r);return `<article><span class="kicker">${r}${r===s.teams[s.team].region?' · HOME':''}</span><h3>${['Uncovered','Local contacts','Regional office','Elite network'][level]}</h3><p>${['Broad estimates · 2 matchweeks','Better estimates · 1 matchweek','Narrow estimates · 1 matchweek','Best estimates · instant reports'][level]}</p><span>${cash([2500,1500,1000,750][level])} per report</span><button data-network="${r}" ${s.match||!cost||E.spendable(s)<cost?'disabled':''}>${cost?'Invest · '+cash(cost):'Fully established'}</button></article>`;}).join('')}</div><details class="networkhelp"><summary>How scouting works</summary><p>Invest once to improve estimates, report prices and speed for players from that region. Two reports reveal exact ability and detailed growth. Draft and offseason reports arrive immediately. Networks stay with the club when you change jobs.</p></details></section>`;}
function scouting(){let ps=s.players.filter(p=>p.team===-1&&(roleFilter==='ALL'||p.role===roleFilter)&&(scoutRegion==='ALL'||p.homeRegion===scoutRegion));return heading('Scouting board',`${ps.length} available players`, `<span class="tag">${cash(s.budget)}</span>`)+networkPanel()+`<div class="regiontabs">${['ALL',...E.regions(s)].map(r=>`<button data-scoutregion="${r}" class="${scoutRegion===r?'active':''}">${r==='ALL'?'All regions':r}</button>`).join('')}</div>`+filters('filter',roleFilter)+(s.phase==='draft'?'<div class="notice">The annual draft is active. Recruit draft prospects through Academy; free-agent signings reopen when Spring begins.</div>':'')+`<div class="scoutgrid">${ps.map(p=>prospectCard(p)).join('')}</div>`;}
function academyView(){const ps=E.academy(s);if(s.phase==='draft'){const picks=s.draft.picks.filter(p=>p.team===s.team);return heading(`${s.year} academy draft`,s.draft.complete?'Your class is ready.':`Three rounds · reverse previous-year results · ${E.academy(s).length}/6 academy slots`,s.draft.complete?'<button class="primary" data-action="spring">Begin Spring →</button>':`<span class="tag gold">PICK #${s.draft.order.indexOf(s.team)+1} / ${s.teams.length} · ROUND ${Math.floor(s.draft.turn/s.teams.length)+1}</span>`)+`<section class="panel"><div class="draftpicks">${[0,1,2].map((_,i)=>{const p=picks[i]&&E.getPlayer(s,picks[i].player);return `<div class="draftpick">${p?portrait(p,'small'):''}<div><strong>${p?playerName(p):'Pick '+(i+1)}</strong><div class="muted textsmall">${p?`${p.role} · ${p.niches[0]}`:'Unselected'}</div></div></div>`;}).join('')}</div></section>${s.draft.complete?`<div class="cards">${ps.map(p=>playerCard(p,true)).join('')}</div>${connectionPanel(ps,true)}`:`<div class="draftlayout"><div>`+filters('draftfilter',draftRole)+`<div class="scoutgrid">${E.draftProspects(s,draftRole).map(p=>prospectCard(p,true)).join('')}</div></div>${draftFeed()}</div>`}${draftOrder()}<details class="detailsbox"><summary>All draft selections</summary><div class="tablewrap"><table><thead><tr><th>Round</th><th>Team</th><th>Player</th><th>Role</th></tr></thead><tbody>${s.draft.picks.map(p=>`<tr><td>${p.round}</td><td>${esc(s.teams[p.team].tag)}</td><td>${playerName(E.getPlayer(s,p.player))}</td><td>${E.getPlayer(s,p.player)?.role||'—'}</td></tr>`).join('')}</tbody></table></div></details>`;}
return heading('Academy',`${ps.length}/6 developing players`, '<button class="small" data-view="training">Set training →</button>')+`<div class="cards">${ps.map(p=>playerCard(p,true)).join('')}</div>${connectionPanel(ps,true)}${!ps.length?'<div class="panel empty"><h2>Your academy is empty.</h2><p>Move bench players back to the academy from their profile or wait for the next annual draft.</p></div>':''}<div class="sectiontitle"><h2>Development league</h2><span class="tag">${s.teams[s.team].region} · ${s.split}</span></div><div class="grid"><section class="panel">${standingsTable(s.teams[s.team].region,true)}</section><section class="panel"><div class="panelbody"><h3>Room to grow</h3><p class="textsmall">Academy squads train and play a development league alongside their region, building connections with each match. Those connections carry into the first team. Former teammates retain familiarity that slowly fades while apart. Call-ups join your first-team bench; select them as a starter in Roster.</p><p class="textsmall">A new class of three players joins every year. Existing academy players remain while under contract.</p></div></section></div>`;}
function contracts(){return heading('Contracts','Negotiate deals and define each player’s role.', '<button class="primary" data-market-tab="negotiations">Agent conversations →</button>')+marketBudget()+marketSquad();}
function season(){const year=seasonYear||s.year,phase=seasonPhase||(s.phase==='draft'?'Spring':s.phase==='offseason'?'Worlds':s.phase.startsWith('international')?s.event:s.split);const regular=['Spring','Summer'].includes(phase),results=s.results.filter(r=>r.year===year&&(regular?r.split===phase&&!r.phase.startsWith('international'):r.event===phase&&r.phase.startsWith('international')));const years=[...new Set([s.year,...s.results.map(r=>r.year)])].sort((a,b)=>b-a);const rows=E.historicalStandings(s,regionFilter,regular?phase:s.split,year);return heading('Season center','Browse the whole competition.',`<select id="season-year" aria-label="Season year">${years.map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select>`)+`<div class="schedulechips">${['Spring','MSI','Summer','Worlds'].map(x=>`<button data-seasonphase="${x}" class="${phase===x?'active':''}">${x}</button>`).join('')}</div>${regular?`<div class="filters">${E.regions(s).map(r=>`<button class="small ${regionFilter===r?'active':''}" data-region="${r}">${r}</button>`).join('')}</div><div class="grid"><section class="panel"><div class="panelhead"><h2>${regionFilter} · ${phase} ${year}</h2></div><table><thead><tr><th>#</th><th>Team</th><th>Series W</th><th>Series L</th></tr></thead><tbody>${rows.map((t,i)=>`<tr class="${t.id===s.team?'you':''}"><td>${i+1}</td><td>${teamLabel(t,true)}</td><td>${t.wins}</td><td>${t.losses}</td></tr>`).join('')}</tbody></table></section><section class="panel fixtures"><div class="panelhead"><h2>Championship rounds</h2></div>${results.filter(r=>r.phase!=='regular'&&s.teams[r.a].region===regionFilter).map(resultRow).join('')||'<div class="panelbody">Championship matches have not been played yet.</div>'}</section></div>`:`<section class="panel"><div class="panelhead"><h2>${phase} ${year}</h2><span class="tag">${phase==='MSI'?'TOP 4 PER REGION':'GROUPS → QUARTERFINALS → SEMIFINALS → FINAL'}</span></div>${phase==='Worlds'?scrimCallout(year):''}${phase==='Worlds'?worldsPanel((s.worldsGroups?.year===year?s.worldsGroups:s.groupHistory?.find(g=>g.year===year))):''}<div class="bracketgrid">${['internationalPlayin','internationalQuarter','internationalSemi','internationalFinal'].filter(stage=>stage!=='internationalPlayin'||phase==='MSI'||results.some(r=>r.phase===stage)).map((stage)=>{const games=results.filter(r=>r.phase===stage);return `<div><h3>${stage==='internationalPlayin'?(phase==='MSI'&&s.teams.length===38?'Round of 16':'Knockout play-in'):stage==='internationalQuarter'?'Quarterfinals':stage==='internationalSemi'?'Semifinals':'Final'}</h3>${games.map(resultRow).join('')||'<p>Not played yet.</p>'}</div>`;}).join('')}</div></section>`}<section class="panel fixtures"><div class="panelhead"><h2>${regular?'Match results':'All series'}</h2></div>${results.filter(r=>!regular||s.teams[r.a].region===regionFilter).map(resultRow).join('')||'<div class="panelbody">No results for this phase yet.</div>'}</section><div class="sectiontitle"><h2>Champions · ${year}</h2></div><div class="hall">${s.honors.filter(h=>h.year===year).map(h=>`<article class="trophy"><span class="cup">♜</span><div>${esc(h.event)}</div><h3>${teamLabel(s.teams[h.winner],true)}</h3><span class="textsmall muted">Runner-up: ${esc(s.teams[h.runner].name)}</span></article>`).join('')||'<p>No champions crowned yet.</p>'}</div><button class="small" data-action="formathelp">Competition format</button>`;}
function resolveMoment(kind){matchTransition(()=>{E.resolveCall(s,kind);const c=s.match?.current?.calls.at(-1)||s.match?.games.at(-1)?.calls.at(-1);if(c)toast((c.worked?'Moment won: ':'Moment lost: ')+(c.swing>=0?'+':'')+c.swing.toFixed(1)+' result points.');});}
function replacementMoment(){const g=s.match.current,ev=E.EVENTS[g.events[g.cursor]],info=E.callPreview(s,'control');return `<section class="panel matchstage"><div class="panelhead"><span class="tag">GAME ${g.number} · EXECUTION MOMENT</span><span>${g.cursor+1} / ${g.events.length}</span></div><div class="situation"><div class="momentweight"><b>${Math.round(info.weight*100)}%</b><span>of the result score hinges on this moment</span></div><h2>${esc(g.skillCheck?.title||'A moment to execute')}</h2><p>${esc(ev.text)}</p><div class="person">${portrait(info.player)}<div><h3>${esc(info.player.name)}</h3><p>${info.player.role} · leading the play</p></div></div><p>This moment replaces the tactical calls. Complete the check, or trust your players’ abilities.</p><div class="actions"><button class="primary" data-action="skillcheck">${g.skillCheck?.status==='complete'?'Review check result':'Take the skill check'}</button>${g.skillCheck?.status==='complete'?'':'<button data-call="auto">Trust the players</button>'}</div><p class="muted">Success +${info.up.toFixed(1)} · miss −${info.down.toFixed(1)} result points.</p></div></section>`;}
function matchView(){const m=s.match;if(!m)return heading('Match center')+preview();const team=s.teams[m.a],opp=s.teams[m.b];const head=heading(`${esc(team.tag)} ${m.score[0]} – ${m.score[1]} ${esc(opp.tag)}`,`${E.phaseLabel(s)} · BO${m.bestOf}`,!m.done?'<button class="small" data-action="sim">Simulate remaining series</button>':'');if(m.current){const g=m.current,ev=E.EVENTS[g.events[g.cursor]];if(E.momentMode(s)==='check')return head+(m.reunion?`<div class="notice">${esc(m.reunion.text)}</div>`:'')+replacementMoment();return head+(m.reunion?`<div class="notice">${esc(m.reunion.text)}</div>`:'')+`<section class="panel matchstage"><div class="panelhead"><span class="tag">GAME ${g.number} · ${ev.time}</span><span>Decision ${g.cursor+1} / ${g.events.length}</span></div><div class="situation"><div class="momentweight"><b>${Math.round(E.momentWeight(ev)*100)}%</b><span>influence on the game’s result score<br><small>Impact weight, not your chance to win.</small></span></div><h2>${ev.title}</h2><p>${ev.text}</p>${captainPanel(m.a)}${ev.calls.map(([role,text,kind])=>{const p=E.starters(s).find(p=>p.role===role),info=E.callPreview(s,kind);return `<button class="decision" data-call="${kind}">${portrait(p)}<span><small>${esc(p.name)} · ${role}</small><strong>“${text}”</strong><span class="risklabel ${kind}">${E.callDescriptor(s,kind)}</span><span class="callnumbers">${Math.round(info.chance*100)}% success · +${info.up.toFixed(1)} / −${info.down.toFixed(1)} result points</span></span></button>`;}).join('')}<button class="small ghost" data-call="auto">Let the players decide →</button></div>${g.calls.map(l=>`<div class="log"><b>${esc(l.player)}</b> · ${esc(l.text)}<br>${l.worked?'The call earned an advantage.':'The opposition denied the plan.'}</div>`).join('')}</section>`;}
 const game=m.games.at(-1),ratings=m.done?E.seriesRatings(m):game.ratings,mvp=ratings.slice().sort((a,b)=>b.rating-a.rating||a.id.localeCompare(b.id))[0],won=m.done?m.won:game.winner===s.team;
 return `<div class="matchresults"><div class="resultheading"><div><span class="kicker">${m.done?'SERIES COMPLETE':'GAME '+game.number+' COMPLETE'} · BO${m.bestOf}</span><h1 class="${won?'resultwin':'resultloss'}">${won?'VICTORY':'DEFEAT'}</h1></div><div class="resultscore">${teamLabel(team)}<b>${m.score[0]} – ${m.score[1]}</b>${teamLabel(opp)}</div><button class="primary" data-action="${m.done?'finish':'nextgame'}">${m.done?'Return to Club':'Start game '+(m.games.length+1)} →</button></div><div class="ratingcaption"><span>${m.done?'Series-average player ratings':'Player ratings · Game '+game.number}</span><span>${mvp?'★ '+esc(mvp.name)+' · '+(m.done?'Series':'Match')+' MVP':''}</span></div>${performanceTable(ratings,mvp?.id)}${m.reunion&&m.games.some(g=>g.mvp===m.reunion.player)?`<div class="notice"><b>The receipt has arrived.</b> ${esc(E.getPlayer(s,m.reunion.player)?.name)} earned a match MVP against their former club. “Nothing personal. Mostly.”</div>`:''}<details class="resultstories" open><summary>What decided ${m.done?'the series':'the game'} · ${m.done?m.games.length+' games':'key moments'}</summary>${(m.done?m.games:[game]).map(g=>`<article><h3>Game ${g.number} · ${teamLabel(s.teams[g.winner])} win</h3><p class="matchstory">${esc(g.summary)}</p>${callRecap(g)}${contestRecap(g)}</article>`).join('')}</details><button class="small ghost" data-action="performancehelp">How ratings and Form work</button></div>`;}

function careerView(){E.recordCareer(s);const c=s.career,x=E.careerStats(s),j=c.jobs;const stat=(label,value,sub='')=>`<article class="careerstat"><span>${label}</span><strong>${value}</strong><small>${sub}</small></article>`;const record=(label,p,suffix='')=>`<article class="careerrecord"><h3>${label}</h3>${p?`<div class="person">${p.portrait!==undefined?portrait(p):''}<div><strong>${esc(p.name)}</strong><p>${p.value!==undefined?p.value.toFixed(1)+suffix:p.count!==undefined?p.count+suffix:''}</p></div></div>${p.team!==undefined?`<small>${teamLabel(s.teams[p.team])} · ${p.year}</small>`:''}`:'<p>No record yet.</p>'}</article>`;return heading('Your career',`${esc(s.manager)} · ${c.stints.length} club${c.stints.length>1?'s':''}`,`<button data-view="hq">Back to Club →</button>`)+`<div class="careerstats">${stat('Series record',x.wins+'–'+x.losses,x.winRate.toFixed(1)+'% win rate')}${stat('Game record',x.gameWins+'–'+x.gameLosses,x.games+' individual games')}${stat('Worlds titles',x.worlds)}${stat('MSI titles',x.msi)}${stat('Regional titles',x.regional)}${stat('Longest win streak',x.longestStreak,'consecutive series')}</div><div class="sectiontitle"><h2>Personal record book</h2><span>Across your clubs</span></div><div class="careerrecords">${record('Highest overall',x.peaks.overall,' OVR')}${record('Highest match rating',x.bestMatch,' / 100')}${record('Most match MVPs',x.mvps[0],' MVPs')}${record('Most games played for you',x.mostPlayed,' games')}<article class="careerrecord"><h3>Strongest connection</h3>${x.peaks.duo?`<strong>${x.peaks.duo.names.map(esc).join(' + ')}</strong><p>${x.peaks.duo.value}% familiarity</p><small>${teamLabel(s.teams[x.peaks.duo.team])} · ${x.peaks.duo.year}</small>`:'<p>No connection recorded yet.</p>'}</article><article class="careerrecord"><h3>Winningest duo</h3>${x.bestDuo?`<strong>${x.bestDuo.names.map(esc).join(' + ')}</strong><p>${(x.bestDuo.wins/x.bestDuo.games*100).toFixed(1)}% · ${x.bestDuo.wins}/${x.bestDuo.games} games</p>`:'<p>Unlocks after a pair plays 10 games together.</p>'}</article><article class="careerrecord"><h3>Longest-tenured player</h3>${x.longestTenure?`<strong>${esc(x.longestTenure.name)}</strong><p>${x.longestTenure.weeks} tracked matchweeks · since ${x.longestTenure.since}</p><small>${teamLabel(s.teams[x.longestTenure.team])}</small>`:'<p>No tenure record yet.</p>'}</article></div><div class="sectiontitle"><h2>Peak player skills</h2></div><div class="careerrecords">${E.SKILLS.map(k=>record(k,x.peaks.skills[k],' / 100')).join('')}</div><section class="panel"><div class="panelhead"><h2>Match MVP leaderboard</h2></div><div class="tablewrap"><table><thead><tr><th>#</th><th>Player</th><th>Match MVPs</th></tr></thead><tbody>${x.mvps.slice(0,12).map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${p.count}</td></tr>`).join('')||'<tr><td colspan="3">Play your first series to start the leaderboard.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panelhead"><h2>Clubs managed</h2></div><div class="panelbody">${c.stints.map(t=>`<div class="pair">${teamLabel(s.teams[t.team],true)}<b>${t.year}–${t.endYear??'present'}</b></div>`).join('')}</div></section>${managerJobs()}<details class="detailsbox"><summary>How Career records are counted</summary><p>Series, individual games, MVPs and titles use saved match history from your management spells. A match MVP means one individual game, not the series-average award. The winningest duo needs ten shared games. Peak skills, overall, connections and tenure are tracked from this update onward; earlier unrecorded peaks cannot be reconstructed.</p></details>`;}
function managerJobs(){const j=s.career?.jobs;if(s.phase!=='offseason'||!j)return '<section class="panel"><div class="panelbody"><h2>Manager opportunities</h2><p>Other clubs may approach you after Worlds. You can stay with your current team or explore a new role.</p></div></section>';const available=['open','dismissed'].includes(j.status)&&s.market.window?.stage==='review';return `<section class="panel managerjobs"><div class="panelhead"><h2>${j.fired?'A new chapter':'Manager opportunities'} · ${j.year+1}</h2>${available&&!j.fired?'<button data-action="staymanager">Stay with my club</button>':''}</div><div class="panelbody"><p>${j.fired?'After a last-place Summer and a full-year win rate below 20%, the board ended your contract. Choose a new role to continue your career.':available?'These are optional offers. Choose before opening free agency; your career records follow you, while each club keeps its players and funds.':j.status==='accepted'?'You accepted the position at '+esc(s.teams[j.accepted].name)+'.':'You are continuing with your current club.'}</p>${available?`<div class="jobcards">${j.offers.map(o=>{const t=s.teams[o.team];return `<article>${teamLabel(t,true)}<span>${t.region} · ${esc(o.reason)}</span><p>Team rating ${E.teamRating(s,t.id).toFixed(0)} · Club funds ${cash(t.funds)}</p><button class="primary" data-job="${t.id}" ${s.celebration?'disabled':''}>Review position →</button></article>`;}).join('')}</div>${s.celebration?'<p>Finish your title celebration in Club before accepting a job.</p>':''}`:''}</div></section>`;}

function settings(){return heading('Settings')+`<section class="panel"><div class="panelhead"><h2>Your career</h2></div><div class="panelbody"><form id="manager-form" class="infoform"><label>Manager name<input name="manager" value="${esc(s.manager)}" maxlength="28" required></label><button class="small" type="submit" style="margin-top:12px">Save name</button></form><div class="actions" style="margin-top:25px"><button class="primary" data-action="export">Export save</button><button data-action="import">Import save</button><button data-action="careers">Saved careers</button><button data-action="new">New career</button>${legacy?'<button data-action="legacyexport">Download original v0.1 save</button>':''}</div><p class="textsmall">Careers autosave in this browser. Export a save to back it up or move it to another device. Achievements are shared across careers here; each export carries that career’s achievements.</p></div></section><section class="panel"><div class="panelhead"><h2>Under the Rift · 1.0</h2></div><div class="panelbody"><p class="textsmall">Four skills shape overall ability. Form (50–100), fatigue, niche combinations and chemistry affect team performance. Form fluctuates with training, traits and match results. Growth responds to your choices; it is not a prewritten career.</p><p class="textsmall">Academies play abstract development matches with their available players. Contracts are negotiated with agents; salary, bonuses, role promises and competing bids shape the deal. Three annual draft picks and two regional splits lead into MSI and Worlds. Players have fictional identities, illustrated portraits and careers shaped by your decisions.</p><p class="textsmall">Real organization names, fictional players, custom competition rules. Champion portraits represent niches; there is no champion-practice selection or pick/ban draft in this version.</p><p class="textsmall">Organization references: <a class="textlink" href="https://lolesports.com/news/lcs-2026-address" target="_blank" rel="noopener">LCS</a> · <a class="textlink" href="https://lolesports.com/en-US/tournament/115548147890329817/stage/115548147896621274" target="_blank" rel="noopener">LCK</a> · <a class="textlink" href="https://lolesports.com/en-US/tournament/115616254668930796/overview" target="_blank" rel="noopener">LPL & team logos</a></p></div></section>`;}
function mascotBadge(t){return `<button class="mascotbutton" data-action="mascot" aria-label="${esc(t.name)} mascot">${badge(t)}</button>`;}
function achievementView(){const book=E.mergeAchievementBooks(sharedAchievements,E.careerAchievementBook(s)),categories=['All',...new Set(E.ACHIEVEMENTS.map(a=>a.category))],unlocked=Object.keys(book.unlocked).length;return heading('Achievements',`${unlocked} / ${E.ACHIEVEMENTS.length} unlocked · Shared across all careers in this browser`)+`<div class="filters">${categories.map(c=>`<button data-achievement-filter="${esc(c)}" class="${achievementFilter===c?'active':''}">${esc(c)}</button>`).join('')}</div><div class="achievementgrid">${E.ACHIEVEMENTS.filter(a=>achievementFilter==='All'||a.category===achievementFilter).map(a=>{const earned=book.unlocked[a.id],hidden=a.secret&&!earned,value=Math.min(a.goal,book.progress[a.metric]||0);return `<article class="achievementcard ${earned?'earned':''}"><span class="achievementicon" aria-hidden="true">${hidden?'?':earned?'◆':'◇'}</span><div><span class="kicker">${esc(a.category)}${earned?' · UNLOCKED':''}</span><h2>${hidden?'Hidden achievement':esc(a.name)}</h2><p>${hidden?'There is more to this club than matchdays.':esc(a.description)}</p>${!hidden&&!earned?`<progress value="${value}" max="${a.goal}" aria-label="${esc(a.name)} progress"></progress><span>${Math.floor(value).toLocaleString()} / ${a.goal.toLocaleString()}</span>`:earned?`<span class="muted">${earned.manager?esc(earned.manager)+' · '+esc(earned.club)+' · '+earned.year:'In your career collection'}</span>`:''}</div></article>`;}).join('')}</div><p class="muted">Unlocks remain when you switch or delete careers. Career milestones use your best individual career; discovered traits and easter eggs are collected across careers.</p>`;}
function secretDialog(title,body){$('#modal').innerHTML=`<div class="panelhead"><h2>${esc(title)}</h2><button data-action="close" aria-label="Close">✕</button></div><div class="modalbody secretbody">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function deskDialog(){const x=E.ensureDiscoveries(s),first=x.first,titles=E.careerStats(s).titles;secretDialog('The manager’s desk',`<div class="deskletter"><span class="kicker">ORIGINAL APPOINTMENT · ${first.year}</span><h2>Welcome, ${esc(first.manager)}.</h2><p>${esc(s.teams[first.team].name)} entrusted you with five players and a very uncertain future. This is where it started.</p></div><h3>The first team photo</h3><div class="deskphoto">${first.roster.map(p=>`<div>${portrait(p)}<b>${esc(p.name)}</b><span>${p.role}</span></div>`).join('')}</div><h3>Kept in the drawer</h3>${titles.length?titles.map(h=>`<div class="news">◆ ${esc(h.event)} ${h.year} · ${teamLabel(s.teams[h.winner],true)}</div>`).join(''):'<p>An empty space for your first winner’s medal.</p>'}`);}
function academyChatDialog(id){secretDialog('Academy · definitely private',`<div class="academychat">${E.academyChat(s,id).map(([name,message])=>`<div class="chatbubble"><b>${esc(name)}</b><p>${esc(message)}</p></div>`).join('')}</div>`);}
function formerPreview(){if(s.match||s.phase==='draft'||s.phase==='offseason')return '';const opp=E.opponent(s);if(opp===undefined)return '';const p=E.formerPlayerLine(s,opp);return p?`<section class="panel"><div class="panelbody"><span class="kicker">A FAMILIAR FACE</span><h3>${esc(p.name)} faces their old club.</h3><p>“Hope you kept the receipt.”</p></div></section>`:'';}
function clubStoriesPanel(){const notices=s.discoveries?.notices||[];if(!notices.length)return '';return `<section class="panel"><div class="panelhead"><h2>Behind the badge</h2><button data-action="scrapbook">Club scrapbook →</button></div>${notices.slice(0,2).map(n=>`<div class="news"><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></div>`).join('')}</section>`;}
function scrapbookDialog(){secretDialog('Club scrapbook',(s.discoveries?.notices||[]).map(n=>`<article class="storyentry"><span class="kicker">${n.year} · WEEK ${n.step}</span><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></article>`).join('')||'<p>The first page is waiting for a story.</p>');}
function playerKeepsake(p){const x=s.discoveries;if(!x)return '';const legend=x.bench[s.team+':'+p.id]?.legend,reunion=x.notices.find(n=>n.player===p.id&&n.id.startsWith('jersey:'));return legend||reunion?`<div class="playerkeepsake">${legend?'<b>◆ The undefeated scrim legend</b><p>A fan favorite, even from the bench.</p>':''}${reunion?'<b>♜ We kept your size.</b><p>Back where an old jersey was waiting.</p>':''}</div>`:'';}
function scrimCallout(year=s.year){const r=s.discoveries?.scrims.find(r=>r.year===year);return r?`<section class="panel scrimcallout"><div class="panelhead"><div><span class="kicker">WORLDS ${year} · AFTER HOURS</span><h2>Who won behind closed doors?</h2></div><button data-scrim-year="${year}">Open scrim records →</button></div></section>`:'';}
function scrimDialog(year=s.year){const reports=s.discoveries?.scrims||[],r=reports.find(r=>r.year===year)||reports.at(-1);if(!r)return;E.discover(s,'scrims');save();secretDialog(`Worlds ${r.year} · scrim records`,`<div class="filters">${reports.map(x=>`<button data-scrim-year="${x.year}" class="${x.year===r.year?'active':''}">${x.year}</button>`).join('')}</div><div class="scrimwinner">${badge(s.teams[r.rows[0].team],true)}<div><span class="kicker">SCRIM WORLD CHAMPIONS</span><h2>${esc(s.teams[r.rows[0].team].name)}</h2><p>${r.rows[0].team===r.champion?'Practice champions. Stage champions. No asterisk needed.':'The practice trophy is imaginary. The bragging rights are very real.'}</p></div></div><p>Private practice games from this Worlds camp. Practice records do not count toward stage standings, championships or prize money.</p><table><thead><tr><th>#</th><th>Team</th><th>W</th><th>L</th><th>Win rate</th></tr></thead><tbody>${r.rows.map((t,i)=>`<tr class="${t.team===s.team?'you':''}"><td>${i+1}</td><td>${teamLabel(s.teams[t.team],true)}${t.team===r.champion?'<span class="tag">STAGE CHAMPION</span>':''}</td><td>${t.wins}</td><td>${t.losses}</td><td>${Math.round(t.wins/(t.wins+t.losses)*100)}%</td></tr>`).join('')}</tbody></table>`);}

function simpleDialog(title,text){$('#modal').innerHTML=`<div class="panelhead"><h2>${esc(title)}</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody"><p>${esc(text)}</p></div>`;$('#modal').showModal();}
function schedulePanel(){const phases=['Draft','Spring','MSI','Summer','Worlds','Offseason'],active=s.phase==='draft'?'Draft':s.phase==='offseason'?'Offseason':s.phase.startsWith('international')?s.event:s.split;const rounds=s.schedules?.[s.teams[s.team].region]||[];return `<section class="panel"><div class="panelhead"><h2>Club schedule · ${s.year}</h2><button class="small" data-view="season">Results →</button></div><div class="timeline">${phases.map(p=>`<span class="${p===active?'current':''}">${p}</span>`).join('')}</div><div class="schedulelist">${s.phase==='regular'?rounds.map((pairs,i)=>{const pair=pairs.find(p=>p.includes(s.team)),opp=pair?.find(t=>t!==s.team),r=s.results.find(r=>r.year===s.year&&r.split===s.split&&r.phase==='regular'&&r.round===i&&(r.a===s.team||r.b===s.team));return `<div class="pair ${i===s.round?'current':''}"><span>Week ${i+1} · ${opp===undefined?'Bye':esc(s.teams[opp].name)}</span><b>${r?r.score?.join(' – ')||'Played':i===s.round?'UP NEXT':'BO3'}</b></div>`;}).join(''):`<div class="pair"><span>${esc(E.phaseLabel(s))}</span><b>${s.phase==='draft'?'3 picks':s.phase==='offseason'?'Renew & rebuild':s.phase==='internationalGroups'?'GROUP SUMMARY':'BO'+E.bestOf(s)}</b></div>${E.fixtures(s).map(([a,b])=>`<p>${esc(s.teams[a].tag)} vs ${esc(s.teams[b].tag)}</p>`).join('')}`}</div></section>`;}
function resultRow(r){return `<button class="seriesrow" data-result="${s.results.indexOf(r)}"><span>${teamLabel(s.teams[r.a])}</span><b>${r.score?r.score.join(' – '):s.teams[r.winner].tag+' win'}</b><span>${teamLabel(s.teams[r.b])}</span><small>${r.phase==='regular'?'Week '+(r.round+1):r.phase.replace('international','').replace('regional','')} ↗</small></button>`;}
function broadcastPanel(){if(!s.broadcast.length)return '';const results=s.results.slice(-s.broadcast.length);return `<section class="panel"><div class="panelhead"><h2>Around the league</h2><button class="small" data-view="season">Tournament center →</button></div><div class="broadcastgrid">${results.map(resultRow).join('')}</div></section>`;}
function draftFeed(){return `<aside class="panel draftfeed"><div class="panelhead"><h2>Draft wire</h2></div>${s.draft.picks.slice().reverse().map(p=>`<div class="news"><span class="tag">ROUND ${p.round} · ${esc(s.teams[p.team].tag)}</span><p><b>${playerName(E.getPlayer(s,p.player))}</b> · ${E.getPlayer(s,p.player)?.role||'—'}</p></div>`).join('')||'<div class="panelbody">You are on the clock.</div>'}</aside>`;}
function performanceTable(ratings,mvp){const teams=[...new Set(ratings.map(r=>r.team))].sort((a,b)=>Number(b===s.team)-Number(a===s.team));return `<div class="performanceboards">${teams.map(id=>{const team=s.teams[id],rows=ratings.filter(r=>r.team===id).sort((a,b)=>E.ROLES.indexOf(a.role)-E.ROLES.indexOf(b.role));return `<section class="performanceboard" style="--team-color:${team.color}"><header>${teamIcon(team)}<div><h3>${esc(team.name)}</h3><span>${id===s.team?'YOUR TEAM':teams.includes(s.team)?'OPPOSITION':team.region}</span></div><span class="ratinglabel">RATING</span></header>${rows.map(r=>`<div class="performancerow ${r.id===mvp?'matchmvp':''}">${portrait(r,'small')}<span class="role">${r.role}</span><div class="performer"><strong>${esc(r.name)}</strong><span>${r.id===mvp?'★ MVP · ':''}Form ${(r.formDelta||0)>=0?'+':''}${(r.formDelta||0).toFixed(1)}</span></div><b class="matchrating">${r.rating.toFixed(1)}</b></div>`).join('')}</section>`;}).join('')}</div>`;}

function callRecap(g){return (g.calls||[]).map(c=>`<div class="callreceipt ${c.worked?'worked':'failed'}"><b>${c.worked?'CALL PAID OFF':'CALL DENIED'} · ${esc(c.player)}</b><p>${esc(c.text)}</p><span>${c.skillCheck?esc(c.skillCheck.type)+' check · '+esc(c.skillCheck.result)+' · ':''}${c.swing!==undefined?`${c.swing>=0?'+':''}${c.swing.toFixed(1)} result points · ${Math.round(c.weight*100)}% moment weight`:c.worked?'Your call created an advantage.':'The opponent stopped the play.'}</span></div>`).join('');}
function contestRecap(g){return g.contests?.length?`<div class="contestrecap" aria-label="Key moments">${g.contests.map(c=>`<div><span>${esc(c.name)}</span>${teamLabel(s.teams[c.winner])}<b>${Math.abs(c.margin)<2?'Narrow edge':Math.abs(c.margin)<7?'Clear edge':'Decisive edge'}</b>${c.story?`<p>${esc(c.story)}</p>`:''}</div>`).join('')}</div>`:'';}
function showResult(i){const r=s.results[i];if(!r)return;$('#modal').innerHTML=`<div class="panelhead"><h2>${esc(s.teams[r.a].tag)} ${r.score?.join(' – ')||'vs'} ${esc(s.teams[r.b].tag)}</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody">${r.games?.map(g=>`<details class="detailsbox" open><summary>Game ${g.number} · ${esc(s.teams[g.winner].tag)} win</summary><p>${esc(g.summary)}</p>${callRecap(g)}${contestRecap(g)}${performanceTable(g.ratings,g.mvp)}</details>`).join('')||'<p>This older result has no detailed game report.</p>'}</div>`;$('#modal').showModal();}
function organizationDialog(){const ev=s.clubEvent;if(!ev)return;const data=E.CLUB_EVENTS.find(e=>e.id===ev.id),scope=data.scope||'team',p=E.getPlayer(s,ev.player),other=E.getPlayer(s,ev.other);$('#modal').innerHTML=`<div class="panelhead"><h2>Inside the club · ${esc(data.category)}</h2><button data-action="close" aria-label="Close event">✕</button></div><div class="eventscene"><div class="eventintro"><div class="scenarioicon" aria-hidden="true">${data.icon||E.EVENT_ICONS[data.category]||'✦'}</div><span class="kicker">A MOMENT OFF THE RIFT</span><h1>${esc(ev.title)}</h1><p>${esc(ev.text)}</p><div class="eventpeople">${scope==='player'||scope==='pair'?portrait(p,'small')+(scope==='pair'?portrait(other,'small'):''):''}<b>${scope==='player'?esc(p.name):scope==='pair'?esc(p.name)+' & '+esc(other.name):scope==='academy'?'Academy squad':'Starting five'}</b></div><span class="eventscope">Effects apply to ${scope==='player'?'this player':scope==='pair'?'this duo':scope==='academy'?'your academy':'your starting five'}, unless stated otherwise.</span></div><div class="eventoptions"><h2>How do you handle it?</h2>${data.choices.map((c,i)=>`<button class="eventchoice" data-orgchoice="${i}" ${(c.mods.cost||0)>E.spendable(s)?'disabled':''}><span class="choicenumber">0${i+1}</span><div><strong>${esc(c.label)}</strong><span>${esc(c.effect)}</span>${(c.mods.cost||0)>E.spendable(s)?'<em>Not enough available funds</em>':''}</div></button>`).join('')}</div></div>`;$('#modal').showModal();}

function celebrationDialog(){const c=s.celebration;if(!c)return;$('#modal').innerHTML=`<div class="celebration ${c.event==='Worlds'?'worlds':''}"><div class="confetti">✦ ★ ✦ ★ ✦</div><span class="kicker">${c.year} · ${esc(c.event)}</span><div class="trophyart">♜</div><h1>${c.event==='Worlds'?'WORLD CHAMPIONS':'CHAMPIONS'}</h1><h2>${esc(s.teams[c.winner].name)}</h2><p>${c.event==='Worlds'?'At the summit of the Rift. This roster made history.':'The work. The calls. The five who brought it home.'}</p><div class="championroster">${c.roster.map(p=>`<div>${portrait(p)}<b>${esc(p.name)}</b><span>${p.role}</span></div>`).join('')}</div><p>Title prize · +${cash(c.prize||E.titlePrize(c.event))}</p><button class="primary" data-action="celebrated">Bring the trophy home →</button></div>`;$('#modal').showModal();}
function combinationDialog(){const active=E.composition(s).links;const rows=E.COMBOS.map(c=>`<tr class="${active.includes(c)?'you':''}"><td><b>${esc(c[2])}</b><p>${esc(c[3])}</p></td><td>${esc(c[0])} + ${esc(c[1])}</td><td>+${c[4]}${active.includes(c)?' ✓':''}</td></tr>`).join('');const hidden=E.SECRET_COMBOS.map(c=>s.discoveries?.combos[c.secretId]?`<tr class="${active.includes(c)?'you':''}"><td><b>✦ ${esc(c[2])}</b><p>${esc(c[3])}</p></td><td>${esc(c[0])} · ${esc(traitName(c.traits[0]))}<br>${esc(c[1])} · ${esc(traitName(c.traits[1]))}</td><td>+${c[4]}${active.includes(c)?' ✓':''}</td></tr>`:'<tr class="lockedcombo"><td><b>???</b><p>Undiscovered connection</p></td><td>??? + ???</td><td>?</td></tr>').join('');$('#modal').innerHTML=`<div class="panelhead"><h2>Composition playbook</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody"><p>The strongest compatible lineup is selected automatically. Normal links cap at +4.5; your strongest hidden link can add up to +1.9.</p><div class="tablewrap"><table><thead><tr><th>Link</th><th>Niches</th><th>Bonus</th></tr></thead><tbody>${rows}</tbody></table></div><h2>Hidden connections · ${Object.keys(s.discoveries?.combos||{}).length} / ${E.SECRET_COMBOS.length}</h2><p>Field rare personalities alongside complementary teammates in a series to discover these links. Different players must supply each half.</p><div class="tablewrap"><table><thead><tr><th>Connection</th><th>Niches & traits</th><th>Bonus</th></tr></thead><tbody>${hidden}</tbody></table></div></div>`;$('#modal').showModal();}

function reportDialog(){$('#modal').innerHTML=`<div class="panelhead"><h2>Development reports</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody"><p>Skill changes from training, match experience, club decisions and natural variation. Offseason reports include preseason camp.</p>${s.reports.slice().reverse().map(r=>`<details class="detailsbox" ${r===s.reports.at(-1)?'open':''}><summary>${r.year} · ${r.type==='offseason'?'Offseason · '+esc(r.camp)+' camp':'Weeks '+r.from+'–'+r.to}</summary>${['Starters','Bench','Academy'].map(group=>{const rows=r.rows.filter(p=>(p.group||(E.getPlayer(s,p.id)?.squad==='academy'?'Academy':s.teams[s.team].lineup[p.role]===p.id?'Starters':'Bench'))===group);return `<h3 class="reportgroup">${group}${group==='Starters'?' · Main roster':''}</h3>${rows.length?`<div class="tablewrap"><table><thead><tr><th>Player</th>${E.SKILLS.map(k=>`<th>${k}</th>`).join('')}${r.type==='offseason'?'<th>Offseason</th>':''}</tr></thead><tbody>${rows.map(p=>`<tr><td><button class="linkbutton" data-profile="${p.id}">${esc(p.name)}</button><small>${p.role}</small></td>${E.SKILLS.map(k=>`<td class="${Number(p.change[k].toFixed(2))<0?'negative':'positive'}">${signed(p.change[k],2)}</td>`).join('')}${r.type==='offseason'?`<td>${esc(p.note)} · Form ${signed(p.formChange)}</td>`:''}</tr>`).join('')}</tbody></table></div>`:'<p class="muted">No players in this group.</p>'}`;}).join('')}</details>`).join('')||'<p>Your first report arrives after four matchweeks.</p>'}</div>`;$('#modal').showModal();}
function draftOrder(){return `<section class="panel"><div class="panelhead"><h2>Draft order</h2><span>Reverse previous-year results</span></div><div class="panelbody"><p>Your slot: <b>#${s.draft.order.indexOf(s.team)+1} of ${s.teams.length}</b> in each round. Overall next pick: #${s.draft.turn+1}. ${E.academy(s).length}/6 academy places filled.</p>${!s.draft.complete?'<div class="actions"><button data-market-tab="squad">Manage roster & releases</button><button data-action="passpick">Pass this pick</button></div>':''}<div class="draftorder">${s.draft.order.map((id,i)=>`<span class="${id===s.team?'you':''}"><b>${i+1}</b> ${teamLabel(s.teams[id])}</span>`).join('')}</div></div></section>`;}
function worldsPanel(stage,action=false){if(!stage)return '';return `<section class="panel"><div class="panelhead"><h2>Worlds · Group stage</h2>${action?nextAction():''}</div><div class="panelbody"><p>${stage.perRegion?'Top '+stage.perRegion+' from each region. ':''}Two advance from each group to the quarterfinals. Summer seeding and roster strength set the odds; the group stage resolves in one summary.</p><div class="worldsgroups">${stage.groups.map(g=>`<div><h3>Group ${g.name}</h3>${g.teams.map(t=>`<div class="pair ${t.team===s.team?'you':''}">${teamLabel(s.teams[t.team])}<b>${stage.resolved?t.advanced?'Advanced ✓':'Eliminated':(t.chance*100).toFixed(1)+'%'}</b></div>`).join('')}</div>`).join('')}</div>${!stage.resolved?'<p class="muted">Percentages are the actual chance to advance, not individual game win chances.</p>':''}</div></section>`;}


let marketTab='overview',marketRole='ALL',marketClub='ALL',marketQuery='',marketPage=0,marketListed=false;
const activeBid=o=>['waiting','counter','agreed'].includes(o.status);
const activeTrade=d=>['incoming','agreed','counter'].includes(d.status);
const playerNames=ids=>ids.map(id=>`<button class="linkbutton" data-offer-profile="${id}">${esc(E.getPlayer(s,id)?.name||'Player')} ↗</button>`).join(' + ')||'No players';
function marketNotice(result){if(result.ok){save();render();}toast(result.message);return result.ok;}
function marketNext(){if(E.managerDecisionPending(s))return '<button class="primary" data-view="career">Manager offers →</button>';const w=s.market.window;if(s.phase!=='offseason')return '';if(w.stage==='review')return '<button class="primary" data-action="openwindowreview">Open free agency →</button>';if(w.stage==='open')return `<button class="primary" data-action="${w.day<6?'advancewindow':'closewindow'}">${w.day<6?'Advance transfer round '+(w.day+1):'Close transfer window'} →</button>`;if(!w.camp)return '<button class="primary" data-market-tab="overview">Choose preseason camp →</button>';return '<button class="primary" data-action="year">Start next year & draft →</button>';}
function marketBudget(){return `<div class="marketstats"><div><span>Available cash</span><strong>${cash(E.spendable(s))}</strong><small>${cash(E.heldCash(s))} held for offers</small></div><div><span>Annual payroll</span><strong>${cash(E.payroll(s))}</strong><small>${cash(s.teams[s.team].wageLimit)} wage budget</small></div><div><span>Wage room after offers</span><strong>${cash(s.teams[s.team].wageLimit-E.committedPayroll(s))}</strong><small>Signing bonuses are paid once</small></div></div>`;}
function marketTimeline(){const w=s.market.window;if(s.phase!=='offseason')return `<div class="marketstatus"><span class="tag gold">${s.phase==='draft'?'PRESEASON':'IN SEASON'}</span><span>${s.phase==='draft'?'Trades and free-agent negotiations are open.':E.marketOpen(s)?'Trades open until your sixth series. '+(5-E.regularSeriesPlayed(s))+' series until the deadline.':'Club trades are closed. No trading during playoffs or internationals.'}</span></div>`;return `<div class="windowtrack">${[['review','Contract review'],['open','Free agency'],['deadline','Deadline'],['closed','Preseason camp']].map(([key,title])=>`<div class="${key===w.stage&&!(key==='open'&&w.day===6)||key==='deadline'&&w.stage==='open'&&w.day===6?'current':''}"><span>${title}</span><strong>${key==='open'?`${w.day} / 6 rounds`:key==='closed'?w.camp||'Build the five':key==='review'?'Retain your core':'Finish your deals'}</strong></div>`).join('')}</div>`;}
function marketClubPanel(){const exp=s.players.filter(p=>p.team===s.team&&p.contract.end===s.year),offers=s.market.inbox.filter(activeTrade).length+s.market.offers.filter(o=>['agreed','counter'].includes(o.status)).length;return `<section class="panel"><div class="panelhead"><h2>${s.phase==='offseason'?'Offseason headquarters':'Recruitment desk'}</h2><button class="small" data-view="market">Open market →</button></div><div class="panelbody"><div class="marketbrief"><div><b>${exp.length}</b><span>expiring contracts</span></div><div><b>${offers}</b><span>offers to review</span></div><div><b>${s.market.shortlist.length}</b><span>shortlisted players</span></div></div>${s.phase==='offseason'?marketTimeline()+marketNext():''}</div></section>`;}
function marketView(){E.ensureMarket(s);const inbox=s.market.inbox.filter(activeTrade).length,bids=s.market.offers.filter(activeBid).length;const tabs=[['overview','Office'],['free','Free agents'],['clubs','Club rosters'],['squad','My squad'],['negotiations',`Negotiations${bids?' · '+bids:''}`],['inbox',`Offers${inbox?' · '+inbox:''}`],['shortlist','Shortlist'],['activity','Transfer wire'],['networks','Scouting networks']];return heading('Transfer office',s.phase==='offseason'?`Building for ${s.year+1}`:'Find the next piece of your team.',marketNext())+marketBudget()+`<nav class="marketnav" aria-label="Transfer sections">${tabs.map(([id,label])=>`<button data-market-tab="${id}" class="${marketTab===id?'active':''}">${label}</button>`).join('')}</nav>`+({overview:marketOverview,free:marketPlayers,clubs:marketPlayers,shortlist:marketPlayers,squad:marketSquad,negotiations:negotiationsView,inbox:tradeInbox,activity:marketActivity,networks:scouting}[marketTab]||marketOverview)();}
function marketOverview(){const w=s.market.window,exp=s.players.filter(p=>p.team===s.team&&p.contract.end===s.year);const ps=E.starters(s);return marketTimeline()+`<div class="marketlayout"><div><section class="panel"><div class="panelhead"><h2>${s.phase==='offseason'&&w.stage==='review'?'Retain, rebuild, or move on':'Your recruitment plan'}</h2><button class="small" data-action="markethelp">How the market works</button></div><div class="panelbody">${s.phase==='offseason'&&w.stage==='review'?`<p>Your ${exp.length} expiring players leave when free agency opens. Negotiate extensions now, or plan their replacements.</p><div class="actions"><button data-market-tab="squad">Review contracts →</button><button data-action="responses">Hear agent responses</button></div>`:s.phase==='offseason'&&w.stage==='closed'?`<h3>${w.camp?'Camp complete. Your next chapter is ready.':'Bring the new roster together.'}</h3><div class="campgrid">${Object.entries(E.CAMPS).map(([name,c])=>`<article><h3>${name}</h3><p>${esc(c.text)}</p><b>${cash(c.cost)}</b><button class="small ${w.camp===name?'primary':''}" data-camp="${name}" ${w.camp||E.spendable(s)<c.cost?'disabled':''}>${w.camp===name?'Completed':'Choose camp'}</button></article>`).join('')}</div>${w.camp?'<div class="actions"><button data-action="reports">Offseason development report</button>'+marketNext()+'</div>':''}`:`<p>${s.phase==='offseason'?'Six transfer rounds. Rival clubs will recruit while your agents respond. Sign agreed deals before their deadlines.':'Build your shortlist now. Negotiate free agents and renewals; agents respond after a matchday, or through the response button in preseason.'}</p><div class="actions"><button class="primary" data-market-tab="free">Explore free agents</button><button data-market-tab="clubs">Approach a club</button>${s.phase==='draft'?'<button data-action="responses">Hear agent responses</button>':''}</div>`}</div></section><section class="panel"><div class="panelhead"><h2>Starting-five outlook</h2><button class="small" data-view="roster">Set lineup →</button></div><div class="outlookgrid">${ps.map(p=>`<article>${portrait(p)}<span class="role">${p.role}</span><button class="linkbutton" data-profile="${p.id}"><b>${esc(p.name)}</b></button><strong>${E.overall(p)}</strong><span class="${p.contract.end===s.year?'negative':''}">${p.emergency?'Reserve replacement':p.contract.end===s.year?'Contract expiring':'Signed to '+p.contract.end}</span><button class="small" data-find-role="${p.role}">Find options</button></article>`).join('')}</div></section>${s.market.ledger.length?`<section class="panel"><div class="panelhead"><h2>Latest business</h2><button class="small" data-market-tab="activity">Full transfer wire →</button></div>${s.market.ledger.slice(0,4).map(marketLog).join('')}</section>`:''}</div><aside><section class="panel"><div class="panelhead"><h2>On your desk</h2></div><div class="panelbody"><button class="deskitem" data-market-tab="negotiations"><b>${s.market.offers.filter(activeBid).length}</b> Active negotiations →</button><button class="deskitem" data-market-tab="inbox"><b>${s.market.inbox.filter(activeTrade).length}</b> Trade offers →</button><button class="deskitem" data-market-tab="squad"><b>${exp.length}</b> Expiring contracts →</button><p class="muted">Contract roles are promises. Players notice when promised starts do not materialize.</p></div></section><section class="panel"><div class="panelhead"><h2>Board brief</h2></div><div class="panelbody"><div class="pair"><span>Club reputation</span><b>${s.teams[s.team].reputation} / 100</b></div><div class="pair"><span>Squad places</span><b>${E.squad(s).length} / 7 main · ${E.academy(s).length} / 6 academy</b></div>${s.phase==='offseason'&&w.grant?`<div class="pair"><span>Offseason investment</span><b>${cash(w.grant)}</b></div>`:''}<p class="muted">Transfers inherit existing contracts. Signing bonuses are reserved while you negotiate. Roster limits: five starters, two bench players, six academy players. Existing over-limit saves retain their players; clear space before adding more.</p></div></section></aside></div>`;}
function marketRating(p){const d=E.scoutTerms(s,p).range;if(!d)return String(E.overall(p));return `${Math.max(50,E.overall(p)-d)}–${Math.min(100,E.overall(p)+d)}`;}
function marketPlayers(){let ps=s.players.filter(p=>marketTab==='free'?p.team===-1:marketTab==='shortlist'?s.market.shortlist.includes(p.id):p.team>=0&&p.team!==s.team);ps=ps.filter(p=>!(s.phase==='draft'&&!s.draft.complete&&s.draft.pool.includes(p.id)&&p.team<0)).filter(p=>(marketRole==='ALL'||p.role===marketRole)&&(marketClub==='ALL'||String(p.team)===marketClub)&&(!marketListed||p.listing==='Listed')&&(!marketQuery||`${p.name} ${p.niches.join(' ')} ${p.traits.join(' ')}`.toLowerCase().includes(marketQuery.toLowerCase()))).sort((a,b)=>E.overall(b)-E.overall(a)||a.id.localeCompare(b.id));const pages=Math.max(1,Math.ceil(ps.length/18));marketPage=Math.min(marketPage,pages-1);return `<div class="marketfilters"><form id="market-search"><input name="query" value="${esc(marketQuery)}" aria-label="Search players" placeholder="Name, niche, or trait"><button class="small" type="submit">Search</button></form><label>Role<select id="market-role">${['ALL',...E.ROLES].map(r=>`<option value="${r}" ${r===marketRole?'selected':''}>${r==='ALL'?'All roles':r}</option>`).join('')}</select></label>${marketTab==='clubs'?`<label>Club<select id="market-club"><option value="ALL">Every club</option>${s.teams.filter(t=>t.id!==s.team).map(t=>`<option value="${t.id}" ${String(t.id)===marketClub?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="checklabel"><input id="listed-only" type="checkbox" ${marketListed?'checked':''}> Transfer listed only</label>`:''}<button class="small" data-action="clearfilters">Clear filters</button></div><div class="sectiontitle"><h2>${marketTab==='free'?'Free agents':marketTab==='shortlist'?'Your shortlist':'Across the league'}</h2><span>${ps.length} players</span></div><div class="marketcards">${ps.slice(marketPage*18,marketPage*18+18).map(p=>{const a=E.askingTerms(s,p),watch=s.market.shortlist.includes(p.id);return `<article class="marketcard"><div class="person">${portrait(p)}<div><span class="role">${p.role} · ${p.age}</span><h3>${playerName(p)}</h3>${captainBadge(p)}<span>${p.team<0?'FREE AGENT':esc(s.teams[p.team].name)}</span></div><strong class="ovr">${marketRating(p)}</strong></div><div class="niches">${p.niches.map(n=>`<span class="tag">${esc(n)}</span>`).join('')}</div><div>${p.traits.map(trait).join('')}</div><div class="marketcardfacts"><span>${p.team<0?'Wants '+cash(a.salary)+'/yr':cash(p.contract.salary)+'/yr · '+p.contract.end}</span><span>${p.preference}</span><span>${p.team<0?'No transfer fee':p.listing==='Untouchable'?'Protected by club':p.listing==='Listed'?'Transfer listed':'Open to approaches'}</span></div><div class="actions"><button class="primary small" data-${p.team<0?'negotiate':'tradefor'}="${p.id}" ${locked()} ${p.listing==='Untouchable'||p.team>=0&&!E.marketOpen(s)?'disabled':''}>${p.team<0?'Negotiate':'Build trade'}</button><button class="small" data-dossier="${p.id}">Scout file</button><button class="small watch ${watch?'selected':''}" data-watch="${p.id}" aria-label="${watch?'Remove from':'Add to'} shortlist">${watch?'★':'☆'}</button></div></article>`;}).join('')||'<section class="panel empty"><h2>No players here yet.</h2><p>Try another filter or add players to your shortlist.</p></section>'}</div><div class="pagination"><button data-market-page="-1" ${marketPage===0?'disabled':''}>← Previous</button><span>${marketPage+1} / ${pages}</span><button data-market-page="1" ${marketPage>=pages-1?'disabled':''}>Next →</button></div>`;}
function marketSquad(){return `<section class="panel"><div class="panelhead"><h2>Your contracts & transfer list</h2><button class="small" data-view="roster">Set starting five →</button></div><div class="tablewrap"><table class="markettable"><thead><tr><th>Player</th><th>Contract</th><th>Playing promise</th><th>Transfer status</th><th>Actions</th></tr></thead><tbody>${s.players.filter(p=>p.team===s.team).map(p=>`<tr><td><div class="person">${portrait(p,'small')}<div><button class="linkbutton" data-profile="${p.id}"><b>${esc(p.name)}</b></button><small>${p.role} · ${E.overall(p)} OVR · ${p.squad==='academy'?'Academy':'First team'}</small></div></div></td><td><b>${cash(p.contract.salary)}/yr</b><small class="${p.contract.end===s.year?'negative':''}">Through ${p.contract.end}${p.contract.end===s.year?' · expiring':''}</small></td><td>${p.contract.role}<small>${p.contract.promise?.eligible?`${p.contract.promise.played}/${p.contract.promise.eligible} starts`:'No start commitment tracked yet'}</small></td><td><select data-listing="${p.id}" aria-label="Transfer status for ${esc(p.name)}" ${locked()}>${['Available','Listed','Untouchable'].map(x=>`<option ${p.listing===x?'selected':''}>${x}</option>`).join('')}</select></td><td><div class="actions"><button class="small" data-negotiate="${p.id}" ${locked()}>Negotiate renewal</button><button class="small ghost" data-release="${p.id}" ${locked()}>Release</button></div></td></tr>`).join('')}</tbody></table></div></section>`;}
function negotiationsView(){const offers=s.market.offers.slice().reverse();return `<div class="sectiontitle"><h2>Agent conversations</h2>${s.phase==='draft'||s.phase==='offseason'&&s.market.window.stage==='review'?'<button class="primary" data-action="responses">Hear agent responses →</button>':s.phase==='offseason'?marketNext():'<span>Responses arrive after your next matchday.</span>'}</div><div class="dealcards">${offers.map(o=>{const p=E.getPlayer(s,o.player);return `<section class="panel dealcard"><div class="panelhead"><div class="person">${portrait(p)}<div><h2><button class="linkbutton" data-offer-profile="${p.id}">${esc(p.name)} ↗</button></h2><span>${p.role} · ${o.renewal?'Renewal':'Recruitment'}</span></div></div><span class="dealstatus ${o.status}">${o.status}</span></div><div class="panelbody"><div class="dealterms"><div><span>Annual salary</span><b>${cash(o.salary)}</b></div><div><span>Signing bonus</span><b>${cash(o.bonus)}</b></div><div><span>Contract</span><b>${o.years} year${o.years>1?'s':''} · ${o.role}</b></div></div><p>${esc(o.message)}</p>${o.status==='counter'?`<div class="counterterms">Agent requests ${cash(o.counter.salary)}/yr + ${cash(o.counter.bonus)} bonus · ${o.counter.years} year${o.counter.years>1?'s':''} · ${o.counter.role}</div>`:''}${o.rivals.length?`<details><summary>${o.rivals.length} rival offer${o.rivals.length>1?'s':''}</summary>${o.rivals.map(r=>`<p>${esc(s.teams[r.team].tag)} · ${cash(r.salary)}/yr · ${r.role}</p>`).join('')}</details>`:''}${activeBid(o)?`<div class="actions">${o.status==='agreed'?`<button class="primary" data-accept-offer="${o.id}">Sign agreed contract</button>`:o.status==='counter'?`<button class="primary" data-negotiate="${o.player}">Revise offer</button>`:''}<button data-withdraw="${o.id}">Withdraw</button><span>Expires after ${Math.max(0,o.expires-s.market.clock)} advances</span></div>`:''}</div></section>`;}).join('')||'<section class="panel empty"><h2>No negotiations yet.</h2><p>Approach a free agent or renew one of your own players.</p><button data-market-tab="free">Find a player →</button></section>'}</div>`;}
function tradeInbox(){return `<div class="sectiontitle"><h2>Club offers</h2><button class="primary" data-action="newtrade" ${!E.marketOpen(s)?'disabled':''}>Build a proposal</button></div><div class="dealcards">${s.market.inbox.map(d=>`<section class="panel dealcard"><div class="panelhead"><h2>${esc(s.teams[d.team].name)}</h2><span class="dealstatus ${d.status}">${d.kind==='incoming'?'Incoming · ':''}${d.status}</span></div><div class="panelbody"><p>${esc(d.message)}</p><div class="tradeexchange"><div><span>YOU SEND</span><h3>${playerNames(d.give)}</h3></div><b>⇄</b><div><span>YOU RECEIVE</span><h3>${playerNames(d.take)}</h3></div></div><p><b>${(d.status==='counter'?d.counterCash:d.cash)>=0?'Cash paid':'Cash received'}: ${cash(Math.abs(d.status==='counter'?d.counterCash:d.cash))}</b></p>${activeTrade(d)?`<div class="actions"><button class="primary" data-complete-trade="${d.id}">Review & complete</button><button data-counter-trade="${d.id}">Counter</button><button data-reject-trade="${d.id}">Decline</button><span>${Math.max(0,d.expires-s.market.clock)} advances left</span></div>`:''}</div></section>`).join('')||'<section class="panel empty"><h2>No club offers yet.</h2><p>List players to attract interest. New proposals arrive during open transfer windows.</p><button data-market-tab="squad">Manage transfer list →</button></section>'}</div>`;}
function marketLog(l){return `<div class="transfernews"><span class="tag">${esc(l.type)}</span><div><p>${esc(l.text)}</p><span>${l.year} · market day ${l.day}</span></div></div>`;}
function marketActivity(){return `<section class="panel"><div class="panelhead"><h2>Transfer wire</h2><span>Both regions · latest first</span></div>${s.market.ledger.map(marketLog).join('')||'<div class="panelbody">Completed moves, renewals and promotions will appear here.</div>'}</section>`;}
function dossier(id){const p=E.getPlayer(s,id);if(!p)return;E.inspectPlayer(s,p);const fit=E.recruitmentFit(s,p);$('#modal').innerHTML=`<div class="panelhead"><h2>Scout file</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody"><div class="profilehero">${portrait(p,'huge')}<div><span class="role">${p.role} · ${p.age}</span><h2>${playerName(p)}</h2>${captainBadge(p)}<p>${p.team<0?'Free agent':esc(s.teams[p.team].name)}</p></div><strong class="ovr">${marketRating(p)}</strong></div><div class="niches">${p.niches.map(n=>`<span class="tag">${esc(n)}</span>`).join('')}</div>${p.traits.map(t=>`<p><b>${esc(traitName(t))}</b> · ${esc(E.TRAITS[t])}</p>`).join('')}<section class="agentnote"><b>Scout assessment</b><p>${prospectNote(p)}</p><p>Current ${p.role}: ${esc(fit.current.name)} · ${E.overall(fit.current)} OVR</p><p>${p.scout===2?`Projected role: ${fit.need}. Individual OVR difference: ${fit.delta>=0?'+':''}${fit.delta}.`:'Scout further before trusting the rating estimate.'}</p></section><p>Priority: <b>${p.preference}</b> · Scouting region: ${p.homeRegion}</p><p>${E.scoutTerms(s,p).days?'Report turnaround: '+E.scoutTerms(s,p).days+' matchweek(s).':'Reports available immediately.'} Network level ${E.scoutTerms(s,p).level} / 3.</p><div class="actions"><button data-scout="${p.id}" ${p.scout===2||s.scouting.includes(p.id)||E.spendable(s)<E.scoutTerms(s,p).cost||s.match?'disabled':''}>${p.scout===2?'Fully scouted':s.scouting.includes(p.id)?'Scout assigned':'Scout · '+cash(E.scoutTerms(s,p).cost)}</button><button data-watch="${p.id}">${s.market.shortlist.includes(p.id)?'★ Shortlisted':'☆ Shortlist'}</button><button class="primary" data-${p.team<0?'negotiate':'tradefor'}="${p.id}" ${s.match||p.team>=0&&!E.marketOpen(s)?'disabled':''}>${p.team<0?'Negotiate':'Build trade'}</button></div></div>`;$('#modal').showModal();}
function negotiationDialog(id){const p=E.getPlayer(s,id);if(!p)return;const prior=s.market.offers.findLast(o=>o.player===id&&activeBid(o)),a=prior?.counter||E.askingTerms(s,p);$('#modal').innerHTML=`<div class="panelhead"><h2>${p.team===s.team?'Renewal':'Contract talks'} · ${esc(p.name)}</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody"><div class="agentnote"><span class="kicker">FROM THE AGENT</span><h3>“${{ 'Playing time':'I want a real role on this team.',Winning:'I want to compete for trophies.',Security:'I want a club that will commit to me.',Salary:'The financial package matters to me.'}[p.preference]}”</h3><p>Prefers ${E.preferredContractYears(p)} year${E.preferredContractYears(p)>1?'s':''}${p.team===s.team?' added to the current deal':''}.</p><p>Target: ${cash(a.salary)}/year · ${cash(a.bonus)} bonus · ${a.years} year${a.years>1?'s':''} · ${a.role}</p></div><form id="offer-form" data-player="${id}"><div class="offerfields"><label>Annual salary ($)<input name="salary" type="number" min="5000" max="200000" step="500" value="${a.salary}" required></label><label>Signing bonus ($)<input name="bonus" type="number" min="0" max="500000" step="500" value="${a.bonus}" required></label><label>${p.team===s.team?'Additional seasons':'Contract length'}<select name="years">${E.CONTRACT_YEARS.map(y=>`<option value="${y}" ${y===a.years?'selected':''}>${y} year${y>1?'s':''}</option>`).join('')}</select></label><label>Promised role<select name="role">${E.SQUAD_ROLES.map(r=>`<option ${r===a.role?'selected':''}>${r}</option>`).join('')}</select></label></div><div id="offer-feedback" class="agentnote"></div><div class="actions"><button type="submit" class="primary" ${s.match?'disabled':''}>Send offer →</button><button type="button" data-action="close">Cancel</button></div></form><p class="muted">The bonus is held until you sign or withdraw. Rival bids can win a free agent before you reach agreement. Starter promises require at least 60% of series starts; Rotation requires 25%.</p></div>`;$('#modal').showModal();offerFeedback();}
function offerTerms(form){const f=new FormData(form);return {salary:Number(f.get('salary')),bonus:Number(f.get('bonus')),years:Number(f.get('years')),role:f.get('role')};}
function offerFeedback(){const form=$('#offer-form');if(!form)return;const p=E.getPlayer(s,form.dataset.player),v=offerTerms(form),e=E.offerEvaluation(s,p,v);$('#offer-feedback').innerHTML=`<b>${e.label}</b><div class="progress"><i style="width:${e.score}%"></i></div>${e.reasons.map(r=>`<p>${esc(r)}</p>`).join('')}<p>Through ${p.team===s.team?Math.max(p.contract.end,s.year)+v.years:E.targetYear(s)+v.years-1}. ${p.team===s.team?'New salary applies immediately. ':''}Signing bonus: ${cash(v.bonus)}.</p>`;}
let tradeDraft=null;
function tradeDialog(team=undefined,target=undefined,base=undefined){tradeDraft=base||{team:team??s.teams.find(t=>t.id!==s.team).id,give:[],take:target?[target]:[],cash:0};const d=tradeDraft;$('#modal').innerHTML=`<div class="panelhead"><h2>Trade builder</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody"><label>Negotiate with<select id="trade-club">${s.teams.filter(t=>t.id!==s.team).map(t=>`<option value="${t.id}" ${t.id===d.team?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><form id="trade-form"><div class="tradecolumns">${[['give',s.team,'You send'],['take',d.team,'You receive']].map(([key,t,title])=>`<div><h3>${title} <small>up to 2</small></h3><div class="tradeselect">${s.players.filter(p=>p.team===t).map(p=>`<label class="tradecheck"><input type="checkbox" name="${key}" value="${p.id}" ${d[key].includes(p.id)?'checked':''} ${key==='take'&&p.listing==='Untouchable'?'disabled':''}>${portrait(p,'small')}<span><b>${esc(p.name)}</b><small>${p.role} · ${E.overall(p)} OVR · ${cash(p.contract.salary)}/yr</small><small>${p.listing}${p.listing==='Listed'?' · discounted':''}</small></span></label>`).join('')}</div></div>`).join('')}</div><label>Cash adjustment ($)<input type="number" name="cash" min="-1000000" max="1000000" step="500" value="${d.cash}"></label><p class="muted">Positive: you pay. Negative: you receive. Existing contracts move with the players.</p><div id="trade-feedback" class="agentnote"></div><button type="submit" class="primary" ${!E.marketOpen(s)?'disabled':''}>Submit proposal →</button></form></div>`;$('#modal').showModal();tradeFeedback();}
function tradeTerms(){const f=new FormData($('#trade-form'));return {team:tradeDraft.team,give:f.getAll('give'),take:f.getAll('take'),cash:Number(f.get('cash'))};}
function tradeFeedback(){if(!$('#trade-form'))return;const q=E.evaluateTrade(s,tradeTerms());$('#trade-feedback').innerHTML=`<b>${q.valid?q.accepted?'Likely agreement':'Expect a counteroffer':'Proposal needs attention'}</b><p>${esc(q.reason)}</p>${q.valid?`<p>Outgoing value: ${cash(q.sent)} · Club asking value: ${cash(q.requested)}</p><p>Your payroll after trade: ${cash(q.userWages)}/year</p>`:''}`;}
function reviewTrade(id){const d=s.market.inbox.find(d=>d.id===id);if(!d)return;const cashValue=d.status==='counter'?d.counterCash:d.cash;$('#modal').innerHTML=`<div class="panelhead"><h2>Complete trade with ${esc(s.teams[d.team].tag)}</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody"><div class="tradeexchange"><div><span>SEND</span><h3>${playerNames(d.give)}</h3></div><b>⇄</b><div><span>RECEIVE</span><h3>${playerNames(d.take)}</h3></div></div><p>${cashValue>=0?'You pay':'You receive'} <b>${cash(Math.abs(cashValue))}</b>.</p><p>Existing salaries and contract expiry dates transfer unchanged. Newly arriving players keep only familiarity earned with teammates they have actually played with.</p><button class="primary" data-finalize-trade="${id}">Complete this trade</button></div>`;$('#modal').showModal();}
function openWindowReview(){const exp=s.players.filter(p=>p.team===s.team&&p.contract.end===s.year);$('#modal').innerHTML=`<div class="panelhead"><h2>Open free agency</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody"><h3>${exp.length?`${exp.length} contracts will expire`:'Your current contracts are secure'}</h3>${exp.map(p=>`<div class="pair"><span>${esc(p.name)} · ${p.role}</span><button class="small" data-negotiate="${p.id}">Negotiate</button></div>`).join('')}<p>Unsigned expiring players enter free agency. Your board releases its offseason investment, and rival clubs begin rebuilding. Any vacant role is filled by your reserves or an academy player; an emergency reserve fills a role only if needed.</p><button class="primary" data-action="openwindow">Open the transfer window</button></div>`;$('#modal').showModal();}

function handleMarketClick(b){
 if(b.dataset.marketTab){marketTab=b.dataset.marketTab;marketClub='ALL';marketListed=false;marketPage=0;view='market';if($('#modal').open)$('#modal').close();render();return true;}
 if(b.dataset.marketPage){marketPage+=Number(b.dataset.marketPage);render();return true;}
 if(b.dataset.findRole){marketRole=b.dataset.findRole;marketTab='free';marketClub='ALL';marketListed=false;marketPage=0;view='market';render();return true;}
 if(b.dataset.editName){const p=E.getPlayer(s,b.dataset.editName);$('#profile-name').innerHTML=`<form id="rename-form" data-player="${p.id}" class="inline-name"><input name="playername" value="${esc(p.name)}" maxlength="24" aria-label="Player name" required><button type="submit" aria-label="Save player name">✓</button><button type="button" data-cancel-name="${p.id}" aria-label="Cancel name edit">✕</button></form>`;$('#profile-name input').focus();$('#profile-name input').select();return true;}
 if(b.dataset.cancelName){openProfile(b.dataset.cancelName,true);return true;}
 if(b.dataset.offerProfile){openProfile(b.dataset.offerProfile,false,true);return true;}
 if(b.dataset.negotiate){negotiationDialog(b.dataset.negotiate);return true;}
 if(b.dataset.dossier){dossier(b.dataset.dossier);save();return true;}
 if(b.dataset.watch){E.toggleShortlist(s,b.dataset.watch);save();b.textContent=s.market.shortlist.includes(b.dataset.watch)?'★':'☆';b.classList.toggle('selected',s.market.shortlist.includes(b.dataset.watch));b.setAttribute('aria-label',s.market.shortlist.includes(b.dataset.watch)?'Remove from shortlist':'Add to shortlist');return true;}
 if(b.dataset.scout&&$('#modal').open){if(E.scout(s,b.dataset.scout)){commit();dossier(b.dataset.scout);toast(s.scouting.includes(b.dataset.scout)?'Scout assigned.':'Scout file updated.');}return true;}
 if(b.dataset.tradefor){const p=E.getPlayer(s,b.dataset.tradefor);tradeDialog(p.team,p.id);return true;}
 if(b.dataset.acceptOffer){marketNotice(E.acceptOffer(s,b.dataset.acceptOffer));return true;}
 if(b.dataset.withdraw){marketNotice(E.withdrawOffer(s,b.dataset.withdraw));return true;}
 if(b.dataset.completeTrade){reviewTrade(b.dataset.completeTrade);return true;}
 if(b.dataset.finalizeTrade){const r=E.completeTrade(s,b.dataset.finalizeTrade);if(r.ok)$('#modal').close();marketNotice(r);return true;}
 if(b.dataset.rejectTrade){marketNotice(E.rejectTrade(s,b.dataset.rejectTrade));return true;}
 if(b.dataset.counterTrade){const d=s.market.inbox.find(x=>x.id===b.dataset.counterTrade);tradeDialog(d.team,undefined,{team:d.team,give:[...d.give],take:[...d.take],cash:d.status==='counter'?d.counterCash:d.cash});return true;}
 if(b.dataset.release){const p=E.getPlayer(s,b.dataset.release);$('#modal').innerHTML=`<div class="panelhead"><h2>Release ${esc(p.name)}</h2><button data-action="close" aria-label="Close dialog">✕</button></div><div class="modalbody"><p>${E.releaseCost(s,p)<0?'Development compensation received':'Contract settlement paid'}: <b>${cash(Math.abs(E.releaseCost(s,p)))}</b>.</p>${p.squad==='academy'?'<p>Prospect contracts may be released without a settlement. After four academy training weeks, a prospect earns a one-time development payment of up to $8,000. Moving a senior player into academy does not waive their contract.</p>':''}<p>The player becomes a free agent immediately. You must have another player covering ${p.role}.</p><button class="primary" data-confirm-release="${p.id}">${E.releaseCost(s,p)<0?'Collect compensation & release':E.releaseCost(s,p)===0?'Release player':'Pay settlement & release'}</button></div>`;$('#modal').showModal();return true;}
 if(b.dataset.confirmRelease){const r=E.releasePlayer(s,b.dataset.confirmRelease);if(r.ok)$('#modal').close();marketNotice(r);return true;}
 if(b.dataset.camp){marketNotice(E.chooseCamp(s,b.dataset.camp));return true;}
 switch(b.dataset.action){
 case'openwindowreview':openWindowReview();return true;
 case'openwindow':{const r=E.openWindow(s);if(r.ok){$('#modal').close();view='market';marketTab='overview';}marketNotice(r);return true;}
 case'advancewindow':marketNotice(E.advanceWindow(s));return true;
 case'closewindow':simpleDialog('Close transfer window?','All outstanding contract offers and club offers will be declined. Completed deals stay in place.');$('#modal .modalbody').insertAdjacentHTML('beforeend','<div class="actions"><button class="primary" data-action="confirmclosewindow">Decline offers & close window</button><button data-action="close">Keep negotiating</button></div>');return true;
 case'confirmclosewindow':{$('#modal').close();const r=E.closeWindow(s);if(r.ok){view='market';marketTab='overview';}marketNotice(r);return true;}
 case'responses':marketTab='negotiations';view='market';marketNotice(E.reviewResponses(s));return true;
 case'newtrade':tradeDialog();return true;
 case'clearfilters':marketRole='ALL';marketClub='ALL';marketQuery='';marketListed=false;marketPage=0;render();return true;
 case'markethelp':simpleDialog('Transfer office','After Worlds, review and renew expiring contracts. Opening free agency releases unsigned players and adds board investment. Six rounds bring rival signings, promotions, trade offers and agent responses. Submit new contract bids before the sixth advance; on deadline day, finish your agreed deals. Contracts use salary, signing bonus, length and a playing-role promise. Rival bids and player priorities affect agreement. Trades carry existing contracts and must leave both clubs able to cover every role. Closing the window declines every outstanding offer after confirmation, then choose a camp and enter the next academy draft. Club trades are also open until five regular-season series have been completed by either club. They are closed during playoffs and internationals. Free agents and renewals can also be negotiated in season; responses arrive after matches.');return true;
 }return false;
}
function handleMarketSubmit(form){if(form.id==='offer-form'){const r=E.submitOffer(s,form.dataset.player,offerTerms(form));if(r.ok){$('#modal').close();marketTab='negotiations';view='market';}marketNotice(r);return true;}if(form.id==='trade-form'){const r=E.submitTrade(s,tradeTerms());if(r.ok){$('#modal').close();marketTab='inbox';view='market';}marketNotice(r);return true;}if(form.id==='market-search'){marketQuery=String(new FormData(form).get('query')).trim();marketPage=0;render();return true;}return false;}
function handleMarketChange(el){if(el.id==='market-role'){marketRole=el.value;marketPage=0;render();return true;}if(el.id==='market-club'){marketClub=el.value;marketPage=0;render();return true;}if(el.id==='listed-only'){marketListed=el.checked;marketPage=0;render();return true;}if(el.dataset.listing){marketNotice(E.setListing(s,el.dataset.listing,el.value));return true;}if(el.id==='trade-club'){tradeDialog(Number(el.value));return true;}if(el.closest('#offer-form')){offerFeedback();return true;}if(el.closest('#trade-form')){tradeFeedback();return true;}return false;}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&e.target.closest('#rename-form')){e.preventDefault();openProfile(currentProfile,true);}});

function render(){const t=s.teams[s.team];$('#app').innerHTML=`<header class="topbar"><div class="wordmark"><i class="riftmark"></i>UNDER THE RIFT</div><div class="topright"><button class="small" data-action="careers">Saved careers</button><button class="small ${view==='achievements'?'active':''}" data-action="achievements">Achievements</button><button class="careerbutton ${view==='career'?'active':''}" data-view="career">Career</button><div class="manager">${mascotBadge(t)}<div><button class="managername" data-action="desk">${esc(s.manager)}</button><span>${esc(t.name)} · ${t.region}</span></div></div><div class="year">${s.year}<small>${s.phase==='draft'?'PRESEASON':s.phase==='offseason'?'OFFSEASON':s.split.toUpperCase()}</small></div><button class="small ghost" data-view="settings" aria-label="Settings">⚙</button></div></header><main class="page" id="main-content" tabindex="-1">${({hq,roster,training,scouting,market:marketView,academy:academyView,contracts,season,career:careerView,achievements:achievementView,match:matchView,settings}[view]||hq)()}<footer class="footer"><span>Under the Rift · 1.0</span></footer></main><nav class="dock" aria-label="Management">${[['hq','⌂','Club'],['roster','♟','Roster'],['training','↗','Training'],['market','⇄','Market'],['academy','◇','Academy'],['contracts','▤','Contracts'],['season','♜','Season']].map(([id,icon,label])=>`<button data-view="${id}" class="${view===id||(id==='hq'&&view==='match')?'active':''}"><span class="icon">${icon}</span>${label}</button>`).join('')}</nav>`;}
function openProfile(id,keep=false,details=false){const p=E.getPlayer(s,id);if(!p)return;E.inspectPlayer(s,p);const own=p.team===s.team;if(own&&!keep){const starters=E.starters(s),main=[...starters,...E.squad(s).filter(x=>!starters.some(a=>a.id===x.id))];profileIds=(view==='training'?(p.squad==='academy'?E.academy(s):main):view==='academy'?E.academy(s):main).map(x=>x.id);if(!profileIds.includes(id))profileIds.push(id);}currentProfile=id;const active=own&&s.teams[s.team].lineup[p.role]===p.id;$('#modal').innerHTML=`<div class="panelhead"><h2>${own||details?'Player profile':'Opponent profile'}</h2>${own?'<div class="profilearrows"><button class="small" data-profile-step="-1" aria-label="Previous player">←</button><span>'+ (profileIds.indexOf(id)+1)+' / '+profileIds.length+'</span><button class="small" data-profile-step="1" aria-label="Next player">→</button></div>':''}<button class="small ghost" data-action="close" aria-label="Close profile">✕</button></div><div class="modalbody"><div class="profilehero">${own&&p.squad==='academy'?`<button class="portraitbutton" data-academy-chat="${p.id}" aria-label="${esc(p.name)} portrait">${portrait(p,'huge')}</button>`:portrait(p,'huge')}<div><span class="kicker">${p.role} · ${p.age} YEARS</span><div class="editname" id="profile-name"><h2>${playerName(p)}</h2>${captainBadge(p)}${own?`<button class="pencil" data-edit-name="${p.id}" aria-label="Edit player name" title="Edit name">✎</button>`:''}</div><div style="margin-top:10px">${p.traits.map(trait).join('')}</div></div><span class="ovr">${E.overall(p)}</span></div><div class="combo-list">${p.niches.map(n=>`<span class="tag">${champion(n)}<span style="margin-left:8px">${esc(n)}</span></span>`).join('')}</div>${playerKeepsake(p)}${formBar(p)}${own||details?`<div class="skills">${E.SKILLS.map(k=>`<div><div class="pair"><span>${k}</span><b>${Math.round(E.effectiveSkill(p,k))}</b></div><div class="progress"><i style="width:${E.effectiveSkill(p,k)}%"></i></div></div>`).join('')}</div><details class="detailsbox"><summary>Growth & advanced information</summary><div class="pair"><span>Learning pace</span><b>${p.learning>1.2?'Fast':p.learning>1?'Above average':'Steady'}</b></div><div class="pair"><span>Estimated growth room</span><b>+${growthRange(p)[0]}–${growthRange(p)[1]} OVR</b></div><div class="pair"><span>Career development</span><b>${signed(E.overall(p)-p.initial)} OVR</b></div><div class="pair"><span>Fatigue</span><b>${Math.round(p.fatigue)} / 100</b></div><div class="pair"><span>Last match performance</span><b>${p.lastPerformance===null?'—':p.lastPerformance}</b></div><div class="historychart">${p.history.slice(-30).map(h=>`<i title="${h.year}: ${h.overall} OVR" style="height:${(h.overall-50)*2}%"></i>`).join('')}</div><p class="textsmall">Skills are 1–100. Displayed skills include passive trait bonuses and penalties. Overall is 50 plus half their effective average. Form is a temporary 50–100 performance state, separate from permanent skill. Potential is a rough estimate, not a hard career cap.</p></details><details class="detailsbox"><summary>Traits & connections</summary>${p.traits.map(t=>`<p class="textsmall"><b>${esc(traitName(t))}:</b> ${E.TRAITS[t]}</p>`).join('')}${p.team>=0?(p.squad==='academy'?E.academy(s,p.team):E.squad(s,p.team)).filter(x=>x.id!==p.id).map(x=>`<div class="pair"><span>${esc(x.name)}</span><b>${E.familiarity(s,p.id,x.id)}% familiarity</b></div>`).join(''):'<p class="muted">No current team connections.</p>'}</details>${own?`<details class="detailsbox"><summary>Contract & release</summary><div class="pair"><span>Annual salary</span><b>${cash(p.contract.salary)}</b></div><div class="pair"><span>Expires</span><b>End of ${p.contract.end}</b></div><button class="small" data-action="contractscreen">Manage contracts →</button> <button class="small" data-release="${p.id}" ${locked()}>Release player</button></details><div class="actions" style="margin-top:18px">${p.squad==='academy'?`<button data-callup="${p.id}" class="primary" ${locked()}>Call up to first team</button>`:!active?`<button data-starter="${p.id}" class="primary" ${locked()}>Start ${p.role}</button><button data-demote="${p.id}" ${locked()}>Move to academy</button>`:'<span class="tag">STARTING PLAYER</span>'}</div>`:''}`:'<p class="textsmall">Opposing roster ratings and niches are visible. Detailed growth assessments are reserved for your own players.</p>'}</div>`;$('#modal').showModal();}
function setup(reset=false){slotNameDraft='';choice=s.team;setupRegion=s.teams[choice].region;managerDraft=started?s.manager:'';drawSetup(reset);$('#modal').showModal();}
function drawSetup(reset=false){$('#modal').innerHTML=`<div class="panelhead"><h2>New career</h2>${reset?'<button class="small ghost" data-action="close">Cancel</button>':''}</div><div class="modalbody intro"><h1>Under the Rift</h1><p>Choose your club. This creates a separate career and keeps your other saves.</p><label>Career name (optional)<input id="slot-name" placeholder="e.g. LEC rebuild" maxlength="60" value="${esc(slotNameDraft)}"></label>${loadError?`<div class="notice">${esc(loadError)}</div>`:''}<label>Your name<input id="manager-name" placeholder="Manager name" maxlength="28" value="${esc(managerDraft)}"></label><div class="regiontabs">${['LCS','LCK','LPL','LEC'].map(r=>`<button data-setupregion="${r}" class="${r===setupRegion?'active':''}">${r}</button>`).join('')}</div><div class="teamchoices">${E.ORGS.map(([name,tag,region,color],id)=>({name,tag,region,color,id})).filter(t=>t.region===setupRegion).map(t=>`<button data-team="${t.id}" class="${t.id===choice?'selected':''}">${badge(t)}${esc(t.name)}</button>`).join('')}</div><div class="introfooter"><button data-action="careers">Saved careers</button><button class="primary" data-action="create">Create career →</button>${legacy&&!reset?'<button data-action="migrate">Bring over v0.1 roster</button>':''}</div>${legacy&&!reset?'<p class="textsmall">Your original save stays intact. Importing brings your starting roster into the new calendar.</p>':''}</div>`;}
function download(data,name){const blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const MATCH_LINES=[
'Checking the river entrances…','The lanes are taking shape…','Watching the next rotation…','Both teams are setting vision…','The carries are finding space…','Tracking the reset timings…','A flank is developing…','The frontline is holding…','Looking for a clean engage…','The map is opening up…','Players are calling their targets…','The next wave is arriving…','Reading the objective setup…','The side lanes are under pressure…','A teamfight is taking shape…','Watching the back line…','The junglers are trading space…','The teams are regrouping…','Looking for a turning point…','The shotcallers are weighing the play…','Checking the pressure across the map…','The next objective is drawing near…','Both teams are choosing their moment…','The supports are clearing vision…','Watching the fight unfold…','The final calls are coming through…','Tracking the strongest lane…','The teams are testing each other…','The tempo is shifting…','Watching for an opening…','The players are committing…','Following the closing moments…'
];
let matchLineDeck=[],lastMatchLine='';
function nextMatchLine(){if(!matchLineDeck.length){matchLineDeck=[...MATCH_LINES];for(let i=matchLineDeck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[matchLineDeck[i],matchLineDeck[j]]=[matchLineDeck[j],matchLineDeck[i]];}if(matchLineDeck.at(-1)===lastMatchLine)[matchLineDeck[0],matchLineDeck[matchLineDeck.length-1]]=[matchLineDeck.at(-1),matchLineDeck[0]];}lastMatchLine=matchLineDeck.pop();return lastMatchLine;}
let matchBusy=false;
async function revealMatchStory(overlay,game){
 if(!game?.contests?.length)return;
 overlay.classList.add('storytransition');overlay.innerHTML=`<div class="broadcastcard"><div class="panelhead"><h2>Game ${game.number} · On the Rift</h2><button class="small" id="skip-broadcast">Skip reveal</button></div><div class="phasebroadcast" aria-live="polite"></div><div class="broadcastfoot">Opening · Objectives · Closing fight</div></div>`;
 let skip=false;overlay.querySelector('#skip-broadcast').onclick=()=>{skip=true;};
 const container=overlay.querySelector('.phasebroadcast');
 for(let i=0;i<game.contests.length;i++){
  const c=game.contests[i],positive=c.winner===s.team;
  container.insertAdjacentHTML('beforeend',`<article class="broadcastphase ${positive?'favorable':'unfavorable'}"><div class="phaseicon">${['⚔','◈','⚑'][i]}</div><div><span class="kicker">PHASE ${i+1} · ${esc(c.name)}</span><h3>${positive?'Advantage '+esc(s.teams[s.team].tag):esc(s.teams[c.winner].tag)+' takes the advantage'}</h3><p>${esc(c.story||c.phrase)}</p><span>${Math.abs(c.cumulative||0)<3?'Still on a knife edge':(c.cumulative>=0?s.teams[s.match.a].tag:s.teams[s.match.b].tag)+' leads the game'}</span></div></article>`);
  if(!skip)await new Promise(resolve=>setTimeout(resolve,transitionDelay()));
 }
}
async function matchTransition(action,drafting=false){
 if(matchBusy)return;matchBusy=true;
 const beforeMatch=s.match,beforeCount=s.match?.games.length||0;
 const overlay=document.createElement('div');overlay.className='matchtransition';overlay.setAttribute('role','status');overlay.setAttribute('aria-live','polite');
 overlay.innerHTML=`<div class="resolvingcard"><div class="matchpulse">${teamIcon(s.teams[s.team])}</div><h2>${drafting?'Around the draft':'On the Rift'}</h2><p>${drafting?'Other clubs are making their selections…':nextMatchLine()}</p><div class="resolutiontrack"><i></i></div></div>`;
 document.body.append(overlay);$('#app').inert=true;
 const duration=transitionDelay(drafting);overlay.dataset.duration=String(duration);overlay.querySelector('.resolutiontrack i').style.animationDuration=duration+'ms';
 try{await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const began=performance.now();action();commit();const remaining=Math.max(0,duration-(performance.now()-began));await new Promise(resolve=>setTimeout(resolve,remaining));
 if(!drafting&&s.match&&(s.match!==beforeMatch||s.match.games.length>beforeCount))await revealMatchStory(overlay,s.match.games.at(-1));
 }catch(error){toast('Could not advance the game: '+error.message);}finally{overlay.remove();$('#app').inert=false;matchBusy=false;}
}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(matchBusy||slotsBusy||!b||b.disabled||(b.type==='submit'&&b.form))return;
if(b.dataset.loadSlot||b.dataset.exportSlot||b.dataset.deleteSlot){await handleSlotClick(b);return;}
if(b.dataset.achievementFilter){achievementFilter=b.dataset.achievementFilter;render();return;}
if(b.dataset.academyChat){const found=E.secretClick(s,'chat',b.dataset.academyChat);save();if(found)academyChatDialog(b.dataset.academyChat);return;}
if(b.dataset.scrimYear){scrimDialog(Number(b.dataset.scrimYear));return;}
if(handleMarketClick(b))return;
if(b.dataset.profileStep){const i=profileIds.indexOf(currentProfile),id=profileIds[(i+Number(b.dataset.profileStep)+profileIds.length)%profileIds.length];openProfile(id,true);save();return;}
if(b.dataset.seasonphase){seasonPhase=b.dataset.seasonphase;render();return;}
if(b.dataset.orgchoice!==undefined){if(E.chooseClubEvent(s,Number(b.dataset.orgchoice))){$('#modal').close();commit();toast(s.clubHistory.at(-1).outcome);}return;}
if(b.dataset.result!==undefined){showResult(Number(b.dataset.result));return;}
if(b.dataset.scoutregion){scoutRegion=b.dataset.scoutregion;render();return;}
if(b.dataset.network){if(E.upgradeNetwork(s,b.dataset.network)){commit();toast('Scouting network upgraded.');}return;}
if(b.dataset.view){view=b.dataset.view;render();return;}
if(b.dataset.profile){openProfile(b.dataset.profile);save();return;}
if(b.dataset.filter){roleFilter=b.dataset.filter;render();return;}
if(b.dataset.draftfilter){draftRole=b.dataset.draftfilter;render();return;}
if(b.dataset.region){regionFilter=b.dataset.region;render();return;}
if(b.dataset.setupregion){slotNameDraft=$('#slot-name').value;managerDraft=$('#manager-name').value;setupRegion=b.dataset.setupregion;choice=E.ORGS.findIndex(t=>t[2]===setupRegion);drawSetup(started);return;}
if(b.dataset.team!==undefined){choice=+b.dataset.team;document.querySelectorAll('[data-team]').forEach(x=>x.classList.toggle('selected',+x.dataset.team===choice));return;}
if(b.dataset.call){resolveMoment(b.dataset.call);return;}
if(b.dataset.action==='skillcheck'){E.prepareReplacementCheck(s);save();mountSkillCheck(s,E,$('#modal'),{save:()=>{save();render();},resolve:resolveMoment});return;}
if(b.dataset.job!==undefined){const id=Number(b.dataset.job);simpleDialog('Join '+s.teams[id].name+'?','Your career records travel with you. Players, funds and contracts remain with their clubs. Current negotiations will be closed.');$('#modal .modalbody').insertAdjacentHTML('beforeend',`<button class="primary" data-confirm-job="${id}">Accept manager position</button>`);return;}
if(b.dataset.confirmJob!==undefined){if(E.acceptManagerJob(s,Number(b.dataset.confirmJob))){$('#modal').close();regionFilter=s.teams[s.team].region;view='career';commit();toast('New club, same career.');}else toast('Choose a club before opening free agency, and finish pending celebrations first.');return;}
if(b.dataset.action==='staymanager'){if(E.stayManager(s))commit();return;}

if(b.dataset.scout){if(E.scout(s,b.dataset.scout)){commit();toast(['draft','offseason'].includes(s.phase)?'Scout report updated.':'Scout assigned. Report arrives in '+E.scoutTerms(s,E.getPlayer(s,b.dataset.scout)).days+' matchweek(s).');}return;}
if(b.dataset.draft){matchTransition(()=>{if(!E.draftPlayer(s,b.dataset.draft))toast('Academy is full. Release a player or pass this pick.');},true);return;}
if(b.dataset.action==='passpick'){matchTransition(()=>E.passDraftPick(s),true);return;}
if(b.dataset.sign){negotiationDialog(b.dataset.sign);return;}
for(const [key,fn,msg] of [['callup',E.callUp,'Called up to your first-team bench.'],['starter',E.setStarter,'Starting lineup updated.'],['demote',E.demote,'Moved to the academy.']]){if(b.dataset[key]){if(fn(s,b.dataset[key])){if($('#modal').open)$('#modal').close();commit();toast(msg);}else toast('Move blocked: maximum 2 bench players and 6 academy players.');return;}}
if(b.dataset.renew){negotiationDialog(b.dataset.renew);return;}
switch(b.dataset.action){case'achievements':E.updateDiscoveries(s);await save();view='achievements';render();break;case'desk':{const found=E.secretClick(s,'desk');save();if(found)deskDialog();break;}case'mascot':E.secretClick(s,'mascot');save();simpleDialog('The mascot has a suggestion',E.mascotOpinion(s));break;case'scrapbook':scrapbookDialog();break;case'scrims':scrimDialog();break;case'nextgame':matchTransition(()=>E.nextSeriesGame(s));break;case'orgevent':organizationDialog();break;case'celebration':celebrationDialog();break;case'celebrated':E.dismissCelebration(s);$('#modal').close();commit();break;case'combinations':combinationDialog();break;case'reports':reportDialog();break;case'balancefive':if(E.setStartingFocus(s,'Balanced')){commit();toast('Starting five set to Balanced. Auto-recovery still applies above your threshold.');}break;case'recoverfive':if(E.recoveryAll(s)){commit();toast('Starting five set to Recovery.');}break;case'traininghelp':simpleDialog('Training & recovery','Automatic recovery overrides a player’s normal training only while fatigue is above your threshold, then resumes their selected plan. It applies to your entire organization. Starting five → Recovery sets those five players’ focus until you change it. Above 50 fatigue, every extra point costs 0.12 Form per normal session; recovery sessions avoid this penalty.');break;case'performancehelp':simpleDialog('Performance ratings','Individual ratings reflect skills, Form, fatigue, traits and game-to-game variation. They feed directly into three key contests that decide each game. MVP is the highest performance rating across both teams; series MVP uses the game average. Form responds to performance relative to a player’s ability, so a good game can improve Form even after defeat.');break;case'formathelp':simpleDialog('Competition format','Regular season: BO3, one decision per series and a 12% chance of a second. Regional playoffs: BO5. Four seeds per region attend MSI: round of 16 and quarterfinals BO3, semifinals and final BO5. Worlds takes four seeds per region into four groups of four; two advance per group, then BO5 quarterfinals, semifinals and final. No Worlds play-in in the four-region calendar. Group odds reflect Summer seeding and current strength. Title prizes: regional $50,000, MSI $125,000, Worlds $250,000. Playoff/international games keep two moments; about 50% replace calls with skill checks. Existing seasons finish their saved calendar; missing regions join at the next draft. This is a custom game format.');break;case'close':if(started)$('#modal').close();else setup();break;case'create':{const name=$('#manager-name').value.trim();if(!name){$('#manager-name').focus();toast('Enter your manager name first.');return;}slotsBusy=true;try{await addCareer(E.newGame(Date.now()>>>0,choice,name),$('#slot-name').value);}catch(error){toast(error.message);}finally{slotsBusy=false;}break;}case'migrate':slotsBusy=true;try{const data=E.migrateV1(JSON.parse(legacy));data.manager=$('#manager-name').value.trim().slice(0,28)||'Coach';await addCareer(data,$('#slot-name').value);}catch(error){toast('Could not import: '+error.message);}finally{slotsBusy=false;}break;case'careers':await savedCareers();break;case'new':setup(true);break;case'play':matchTransition(()=>{E.enterMatchday(s);view=s.match?'match':'hq';});break;case'sim':matchTransition(()=>E.fastForward(s));break;case'finish':E.finishMatchday(s);view='hq';commit();break;case'spring':E.finishDraft(s);view='hq';commit();break;case'year':if(E.nextYear(s)){view='academy';commit();}else toast('Finish the transfer window and choose a preseason camp first.');break;case'contractscreen':$('#modal').close();view='contracts';render();break;case'export':download(JSON.stringify(s,null,2),'under-the-rift-save.json');break;case'legacyexport':download(legacy,'front-office-original-save.json');break;case'import':$('#import').click();break;}
});
document.addEventListener('submit',async e=>{e.preventDefault();if(slotsBusy||matchBusy)return;if(e.target.matches('.slot-rename')){slotsBusy=true;try{await careerStore.rename(e.target.dataset.slot,new FormData(e.target).get('slotname'));slotsBusy=false;await savedCareers();}catch(error){toast(error.message);}finally{slotsBusy=false;}return;}if(handleMarketSubmit(e.target))return;if(e.target.id==='rename-form'){const id=e.target.dataset.player;const name=new FormData(e.target).get('playername');if(E.rename(s,id,name)){$('#modal').close();commit();openProfile(id,true);toast('Player renamed.');}}if(e.target.id==='manager-form'){const name=String(new FormData(e.target).get('manager')).trim().slice(0,28);if(name){s.manager=name;commit();toast('Manager name saved.');}}});
document.addEventListener('change',e=>{const el=e.target;if(handleMarketChange(el))return;if(el.id==='season-year'){seasonYear=Number(el.value);render();return;}if(el.id==='auto-recovery'){if(!s.match){s.recovery.enabled=el.checked;commit();}return;}if(el.id==='recovery-threshold'){if(!s.match){s.recovery.threshold=Number(el.value);commit();}return;}if(el.dataset.years){renewYears[el.dataset.years]=+el.value;render();return;}if(s.match)return;const id=el.dataset.focus||el.dataset.intensity;if(!id)return;const p=E.getPlayer(s,id);if(p?.team!==s.team)return;if(el.dataset.focus&&E.FOCUSES.includes(el.value))p.focus=el.value;if(el.dataset.intensity&&['Light','Normal','Intense'].includes(el.value))p.intensity=el.value;commit();});
$('#import').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(slotsBusy||matchBusy){e.target.value='';return;}slotsBusy=true;try{if(f.size>100000000)throw Error('Save is too large.');const data=JSON.parse(await f.text());const loaded=data.version===1?E.migrateV1(data):E.validateSave(data);await addCareer(loaded,defaultCareerName(loaded)+' · imported');toast('Imported as a separate career.');}catch(err){toast('Import failed: '+err.message);}finally{e.target.value='';slotsBusy=false;}});
document.addEventListener('input',e=>{if(e.target.closest('#offer-form'))offerFeedback();if(e.target.closest('#trade-form'))tradeFeedback();if(e.target.id==='recovery-threshold')$('#threshold-value').textContent=e.target.value;});
$('#modal').addEventListener('cancel',e=>{if(!started)e.preventDefault();});
render();if(!started)setup();
